/**
 * Target checks shared by the Playwright capture scripts.
 *
 * Both run Chromium with `--no-sandbox` as root and take their URL and output
 * path from argv, so unchecked they will render `file:///root/.grok/auth.json`
 * into a PNG the agent can read, and write it anywhere.
 */
import { resolve, sep } from "node:path";

const LOOPBACK_HOSTNAMES = new Set(["127.0.0.1", "localhost", "::1", "[::1]"]);

/** http/https loopback only, else exit 1. `BROWSER_ALLOW_EXTERNAL_HOST=1` opts out. */
export function checkedUrl(url) {
  let parsed;
  try {
    parsed = new URL(url);
  } catch {
    fail(`not a valid URL: ${url}`);
  }
  // Rules out file:, data:, chrome:, view-source:.
  if (parsed.protocol !== "http:" && parsed.protocol !== "https:") {
    fail(`only http/https URLs are allowed, got ${parsed.protocol} in ${url}`);
  }
  if (!LOOPBACK_HOSTNAMES.has(parsed.hostname) && process.env.BROWSER_ALLOW_EXTERNAL_HOST !== "1") {
    fail(
      `${parsed.hostname} is not a loopback host; these scripts screenshot the ` +
        `local dev server. Set BROWSER_ALLOW_EXTERNAL_HOST=1 to override.`,
    );
  }
  return url;
}

/** Absolute `target` if it is strictly inside `allowedDirs`, else exit 1. */
export function checkedOutputPath(target, allowedDirs, label = "screenshot") {
  // Resolve first so `..` cannot slip past the prefix check.
  const abs = resolve(target);
  const allowed = allowedDirs.some((dir) => abs.startsWith(dir.endsWith(sep) ? dir : dir + sep));
  if (!allowed) {
    fail(`${label} path must be under ${allowedDirs.join(" or ")}, got ${abs}`);
  }
  return abs;
}

function fail(message) {
  console.error(JSON.stringify({ ok: false, error: message }, null, 2));
  process.exit(1);
}

import { createHash } from "node:crypto";
export function normalizeBodyText(text) {
  return String(text ?? "")
    .replace(/\s+/g, " ")
    .trim();
}

export function normalizedBodyTextHash(text) {
  return createHash("sha256").update(normalizeBodyText(text)).digest("hex");
}

const IDENTITY_PREFIX_LEN = 64;

export function bodyTextPrefix(text) {
  return normalizeBodyText(text).slice(0, IDENTITY_PREFIX_LEN);
}
export function parseSmokeArgs(argv, env = {}) {
  const positional = [];
  let baseline = env.BROWSER_SMOKE_BASELINE || "";
  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    if (arg === "--baseline") {
      const value = argv[++i];
      if (!value) return { error: "--baseline requires a path to a prior verdict JSON" };
      baseline = value;
    } else if (arg.startsWith("--baseline=")) {
      const value = arg.slice("--baseline=".length);
      if (!value) return { error: "--baseline requires a path to a prior verdict JSON" };
      baseline = value;
    } else if (arg.startsWith("--")) {
      return { error: `unknown flag: ${arg}` };
    } else {
      positional.push(arg);
    }
  }
  return {
    url: positional[0] || "http://127.0.0.1:8080/",
    outPng: positional[1] || "/workspace/screenshots/app-builder-preview.png",
    baseline,
  };
}
export function derivedPaths(outPng) {
  const base = outPng.replace(/\.png$/i, "");
  return { mobilePng: `${base}-mobile.png`, verdictJson: `${base}.json` };
}

const TRIVIAL_LEN_DELTA = 20;
const TRIVIAL_LEN_RATIO = 0.1;
const COLLAPSE_RATIO = 0.5;
export function compareToBaseline(current, baseline) {
  const entries = Object.entries(current?.viewports ?? {});
  if (entries.length === 0) {
    return {
      divergesFromBaseline: true,
      reasons: ["current verdict has no viewport data"],
    };
  }
  const reasons = [];
  const baseViewports = baseline?.viewports ?? {};
  for (const [name, cur] of entries) {
    const base = baseViewports[name];
    if (!base) {
      reasons.push(`${name}: no baseline data for this viewport`);
      continue;
    }
    if (cur.status !== base.status) {
      reasons.push(`${name}: HTTP status changed ${base.status} -> ${cur.status}`);
    }
    if (base.title !== undefined && cur.title !== undefined && cur.title !== base.title) {
      reasons.push(`${name}: title changed ("${base.title}" -> "${cur.title}")`);
    }
    if (base.hasCanvas && !cur.hasCanvas) {
      reasons.push(`${name}: canvas disappeared`);
    }
    if (cur.horizontalOverflow && !base.horizontalOverflow) {
      reasons.push(`${name}: horizontal overflow appeared`);
    }
    const baseErrs = (base.consoleErrors?.length ?? 0) + (base.pageErrors?.length ?? 0);
    const curErrs = (cur.consoleErrors?.length ?? 0) + (cur.pageErrors?.length ?? 0);
    if (curErrs > 0 && baseErrs === 0) {
      reasons.push(`${name}: console/page errors appeared (${curErrs})`);
    }
    const baseLen = base.bodyTextLen ?? 0;
    const curLen = cur.bodyTextLen ?? 0;
    if (baseLen > 0 && curLen < baseLen * COLLAPSE_RATIO) {
      reasons.push(`${name}: body text collapsed (${baseLen} -> ${curLen} chars)`);
    } else if (cur.bodyTextHash !== base.bodyTextHash) {
      if (Math.abs(curLen - baseLen) > Math.max(TRIVIAL_LEN_DELTA, baseLen * TRIVIAL_LEN_RATIO)) {
        reasons.push(`${name}: body text changed (${baseLen} -> ${curLen} chars, hash mismatch)`);
      } else if (
        base.bodyTextPrefix !== undefined &&
        cur.bodyTextPrefix !== undefined &&
        cur.bodyTextPrefix !== base.bodyTextPrefix
      ) {
        reasons.push(`${name}: body text replaced (similar length, page start changed)`);
      }
    }
  }
  return { divergesFromBaseline: reasons.length > 0, reasons };
}
export function baselineComparison(current, rawText) {
  let baseline;
  try {
    baseline = JSON.parse(rawText);
  } catch {
    return { divergesFromBaseline: true, reasons: ["baseline unreadable: invalid JSON"] };
  }
  if (
    baseline === null ||
    typeof baseline !== "object" ||
    Array.isArray(baseline) ||
    baseline.viewports === null ||
    typeof baseline.viewports !== "object" ||
    Array.isArray(baseline.viewports)
  ) {
    return { divergesFromBaseline: true, reasons: ["baseline unreadable: not a verdict object"] };
  }
  return compareToBaseline(current, baseline);
}
export function exitCodeFor(viewports) {
  const list = Object.values(viewports ?? {});
  if (list.length === 0) return 1;
  if (list.some((v) => (v.status ?? 0) >= 400 || (v.status ?? 0) === 0)) return 1;
  if (list.some((v) => (v.consoleErrors?.length ?? 0) > 0 || (v.pageErrors?.length ?? 0) > 0)) {
    return 2;
  }
  return 0;
}

import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import test from "node:test";
import {
  baselineComparison,
  bodyTextPrefix,
  compareToBaseline,
  derivedPaths,
  exitCodeFor,
  normalizeBodyText,
  normalizedBodyTextHash,
  parseSmokeArgs,
} from "./browser-smoke-verdict.mjs";

const TEMPLATE_ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");

function viewport(overrides = {}) {
  return {
    status: 200,
    title: "App",
    hasCanvas: false,
    horizontalOverflow: false,
    bodyTextLen: 500,
    bodyTextHash: "aaa",
    bodyTextPrefix: "hello world",
    consoleErrors: [],
    pageErrors: [],
    ...overrides,
  };
}

function verdict(desktop = {}, mobile = {}) {
  return { viewports: { desktop: viewport(desktop), mobile: viewport(mobile) } };
}

test("normalizes whitespace before hashing", () => {
  assert.equal(normalizeBodyText("  a \n\t b  "), "a b");
  assert.equal(normalizedBodyTextHash("a \n b"), normalizedBodyTextHash("  a b "));
  assert.notEqual(normalizedBodyTextHash("a b"), normalizedBodyTextHash("a c"));
});

test("nullish and blank body text normalize to the empty string", () => {
  assert.equal(normalizeBodyText(null), "");
  assert.equal(normalizeBodyText(undefined), "");
  assert.equal(normalizedBodyTextHash(""), normalizedBodyTextHash("  \n "));
});

test("body text prefix is normalized and capped", () => {
  assert.equal(bodyTextPrefix("  a \n b  "), "a b");
  assert.equal(bodyTextPrefix("x".repeat(200)).length, 64);
});

test("identical runs do not diverge", () => {
  const { divergesFromBaseline, reasons } = compareToBaseline(verdict(), verdict());
  assert.equal(divergesFromBaseline, false);
  assert.deepEqual(reasons, []);
});

test("status change diverges", () => {
  const { divergesFromBaseline, reasons } = compareToBaseline(verdict({ status: 500 }), verdict());
  assert.equal(divergesFromBaseline, true);
  assert.match(reasons.join(";"), /desktop: HTTP status changed 200 -> 500/);
});

test("title change diverges", () => {
  const { divergesFromBaseline, reasons } = compareToBaseline(
    verdict({ title: "Error" }),
    verdict(),
  );
  assert.equal(divergesFromBaseline, true);
  assert.match(reasons.join(";"), /desktop: title changed \("App" -> "Error"\)/);
});

test("title comparison is skipped when either side lacks one", () => {
  const { divergesFromBaseline } = compareToBaseline(
    verdict({ title: undefined }),
    verdict({ title: "App" }),
  );
  assert.equal(divergesFromBaseline, false);
});

test("canvas disappearing diverges; canvas appearing does not", () => {
  const gone = compareToBaseline(verdict({ hasCanvas: false }), verdict({ hasCanvas: true }));
  assert.equal(gone.divergesFromBaseline, true);
  assert.match(gone.reasons.join(";"), /desktop: canvas disappeared/);

  const appeared = compareToBaseline(verdict({ hasCanvas: true }), verdict({ hasCanvas: false }));
  assert.equal(appeared.divergesFromBaseline, false);
});

test("horizontal overflow appearing diverges; clearing does not", () => {
  const appeared = compareToBaseline(
    verdict({}, { horizontalOverflow: true }),
    verdict({}, { horizontalOverflow: false }),
  );
  assert.equal(appeared.divergesFromBaseline, true);
  assert.match(appeared.reasons.join(";"), /mobile: horizontal overflow appeared/);

  const cleared = compareToBaseline(
    verdict({}, { horizontalOverflow: false }),
    verdict({}, { horizontalOverflow: true }),
  );
  assert.equal(cleared.divergesFromBaseline, false);
});

test("new console errors diverge", () => {
  const { divergesFromBaseline, reasons } = compareToBaseline(
    verdict({}, { consoleErrors: ["boom"] }),
    verdict(),
  );
  assert.equal(divergesFromBaseline, true);
  assert.match(reasons.join(";"), /mobile: console\/page errors appeared/);
});

test("errors already present in the baseline do not re-diverge", () => {
  const { divergesFromBaseline } = compareToBaseline(
    verdict({ consoleErrors: ["boom"] }),
    verdict({ consoleErrors: ["boom"] }),
  );
  assert.equal(divergesFromBaseline, false);
});

test("body text collapse diverges", () => {
  const { divergesFromBaseline, reasons } = compareToBaseline(
    verdict({ bodyTextLen: 10, bodyTextHash: "bbb" }),
    verdict(),
  );
  assert.equal(divergesFromBaseline, true);
  assert.match(reasons.join(";"), /desktop: body text collapsed \(500 -> 10 chars\)/);
});

test("body text dropping to zero reports collapse", () => {
  const { reasons } = compareToBaseline(
    verdict({ bodyTextLen: 0, bodyTextHash: "bbb", bodyTextPrefix: "" }),
    verdict(),
  );
  assert.match(reasons.join(";"), /desktop: body text collapsed \(500 -> 0 chars\)/);
});

test("zero-length baseline reports growth via the hash branch, not collapse", () => {
  const { reasons } = compareToBaseline(
    verdict({ bodyTextLen: 500 }),
    verdict({ bodyTextLen: 0, bodyTextHash: "bbb", bodyTextPrefix: "" }),
  );
  assert.match(reasons.join(";"), /desktop: body text changed \(0 -> 500 chars/);
});

test("hash mismatch with a trivial length delta and same page start is tolerated", () => {
  const { divergesFromBaseline } = compareToBaseline(
    verdict({ bodyTextLen: 510, bodyTextHash: "bbb" }),
    verdict(),
  );
  assert.equal(divergesFromBaseline, false);
});

test("hash mismatch with a trivial length delta but changed page start diverges", () => {
  const { divergesFromBaseline, reasons } = compareToBaseline(
    verdict({ bodyTextLen: 510, bodyTextHash: "bbb", bodyTextPrefix: "500 Internal Error" }),
    verdict(),
  );
  assert.equal(divergesFromBaseline, true);
  assert.match(
    reasons.join(";"),
    /desktop: body text replaced \(similar length, page start changed\)/,
  );
});

test("prefix check is skipped when either side lacks a prefix", () => {
  const cases = [
    [{ bodyTextPrefix: undefined }, { bodyTextPrefix: undefined }],
    [{}, { bodyTextPrefix: undefined }],
    [{ bodyTextPrefix: undefined }, {}],
  ];
  for (const [curOverrides, baseOverrides] of cases) {
    const { divergesFromBaseline } = compareToBaseline(
      verdict({ bodyTextLen: 510, bodyTextHash: "bbb", ...curOverrides }),
      verdict(baseOverrides),
    );
    assert.equal(divergesFromBaseline, false);
  }
});

test("length-delta tolerance boundary: 50 tolerated, 51 diverges (500-char baseline)", () => {
  const at = compareToBaseline(verdict({ bodyTextLen: 550, bodyTextHash: "bbb" }), verdict());
  assert.equal(at.divergesFromBaseline, false);

  const over = compareToBaseline(verdict({ bodyTextLen: 551, bodyTextHash: "bbb" }), verdict());
  assert.equal(over.divergesFromBaseline, true);
  assert.match(over.reasons.join(";"), /desktop: body text changed/);
});

test("length-delta floor dominates small baselines: 20 tolerated, 21 diverges (100-char baseline)", () => {
  const base = verdict({ bodyTextLen: 100 }, { bodyTextLen: 100 });
  const at = compareToBaseline(
    verdict({ bodyTextLen: 120, bodyTextHash: "bbb" }, { bodyTextLen: 100 }),
    base,
  );
  assert.equal(at.divergesFromBaseline, false);

  const over = compareToBaseline(
    verdict({ bodyTextLen: 121, bodyTextHash: "bbb" }, { bodyTextLen: 100 }),
    base,
  );
  assert.equal(over.divergesFromBaseline, true);
});

test("collapse boundary: exactly half is 'changed', one below is 'collapsed'", () => {
  const half = compareToBaseline(verdict({ bodyTextLen: 250, bodyTextHash: "bbb" }), verdict());
  assert.match(half.reasons.join(";"), /desktop: body text changed \(500 -> 250 chars/);

  const below = compareToBaseline(verdict({ bodyTextLen: 249, bodyTextHash: "bbb" }), verdict());
  assert.match(below.reasons.join(";"), /desktop: body text collapsed \(500 -> 249 chars\)/);
});

test("missing baseline viewport diverges", () => {
  const { divergesFromBaseline, reasons } = compareToBaseline(verdict(), {
    viewports: { desktop: viewport() },
  });
  assert.equal(divergesFromBaseline, true);
  assert.match(reasons.join(";"), /mobile: no baseline data/);
});

test("empty or null baseline diverges for every viewport", () => {
  for (const baseline of [{}, null]) {
    const { divergesFromBaseline, reasons } = compareToBaseline(verdict(), baseline);
    assert.equal(divergesFromBaseline, true);
    assert.match(reasons.join(";"), /desktop: no baseline data/);
    assert.match(reasons.join(";"), /mobile: no baseline data/);
  }
});

test("degenerate current verdict fails closed", () => {
  for (const current of [null, undefined, {}, { viewports: {} }]) {
    const { divergesFromBaseline, reasons } = compareToBaseline(current, verdict());
    assert.equal(divergesFromBaseline, true);
    assert.deepEqual(reasons, ["current verdict has no viewport data"]);
  }
});

test("multiple signals across viewports all accumulate", () => {
  const { reasons } = compareToBaseline(
    verdict({ status: 500 }, { consoleErrors: ["boom"] }),
    verdict(),
  );
  assert.match(reasons.join(";"), /desktop: HTTP status changed/);
  assert.match(reasons.join(";"), /mobile: console\/page errors appeared/);
  assert.equal(reasons.length, 2);
});

test("baselineComparison round-trips a valid baseline", () => {
  const { divergesFromBaseline } = baselineComparison(verdict(), JSON.stringify(verdict()));
  assert.equal(divergesFromBaseline, false);
});

test("baselineComparison fails closed on malformed or wrong-shape baselines", () => {
  for (const raw of ["{", "", "not json"]) {
    const { divergesFromBaseline, reasons } = baselineComparison(verdict(), raw);
    assert.equal(divergesFromBaseline, true);
    assert.deepEqual(reasons, ["baseline unreadable: invalid JSON"]);
  }
  for (const raw of [
    "null",
    "[]",
    "0",
    "false",
    '""',
    "{}",
    '{"viewports": null}',
    '{"viewports": []}',
  ]) {
    const { divergesFromBaseline, reasons } = baselineComparison(verdict(), raw);
    assert.equal(divergesFromBaseline, true);
    assert.deepEqual(reasons, ["baseline unreadable: not a verdict object"]);
  }
});

test("parseSmokeArgs defaults", () => {
  assert.deepEqual(parseSmokeArgs([], {}), {
    url: "http://127.0.0.1:8080/",
    outPng: "/workspace/screenshots/app-builder-preview.png",
    baseline: "",
  });
});

test("parseSmokeArgs consumes --baseline without shifting positionals", () => {
  assert.deepEqual(
    parseSmokeArgs(
      ["http://127.0.0.1:8081/", "--baseline", "/workspace/a.json", "/workspace/b.png"],
      {},
    ),
    {
      url: "http://127.0.0.1:8081/",
      outPng: "/workspace/b.png",
      baseline: "/workspace/a.json",
    },
  );
});

test("parseSmokeArgs rejects a trailing --baseline flag", () => {
  assert.deepEqual(parseSmokeArgs(["--baseline"], {}), {
    error: "--baseline requires a path to a prior verdict JSON",
  });
});

test("parseSmokeArgs supports the --baseline= form", () => {
  assert.equal(parseSmokeArgs(["--baseline=/workspace/a.json"], {}).baseline, "/workspace/a.json");
  assert.deepEqual(parseSmokeArgs(["--baseline="], {}), {
    error: "--baseline requires a path to a prior verdict JSON",
  });
});

test("parseSmokeArgs rejects unknown flags instead of treating them as positionals", () => {
  assert.deepEqual(parseSmokeArgs(["--nope"], {}), { error: "unknown flag: --nope" });
  assert.deepEqual(
    parseSmokeArgs(["http://127.0.0.1:8080/", "--Baseline", "/workspace/a.json"], {}),
    {
      error: "unknown flag: --Baseline",
    },
  );
});

test("parseSmokeArgs env fallback and flag precedence", () => {
  const env = { BROWSER_SMOKE_BASELINE: "/workspace/env.json" };
  assert.equal(parseSmokeArgs([], env).baseline, "/workspace/env.json");
  assert.equal(
    parseSmokeArgs(["--baseline", "/workspace/flag.json"], env).baseline,
    "/workspace/flag.json",
  );
});

test("derivedPaths handles .png, .PNG, and extensionless inputs", () => {
  assert.deepEqual(derivedPaths("/workspace/shot.png"), {
    mobilePng: "/workspace/shot-mobile.png",
    verdictJson: "/workspace/shot.json",
  });
  assert.deepEqual(derivedPaths("/workspace/shot.PNG"), {
    mobilePng: "/workspace/shot-mobile.png",
    verdictJson: "/workspace/shot.json",
  });
  assert.deepEqual(derivedPaths("/workspace/shot"), {
    mobilePng: "/workspace/shot-mobile.png",
    verdictJson: "/workspace/shot.json",
  });
});

test("exitCodeFor: clean run exits 0", () => {
  assert.equal(exitCodeFor(verdict().viewports), 0);
});

test("exitCodeFor: errors in any single viewport exit 2", () => {
  assert.equal(exitCodeFor(verdict({}, { consoleErrors: ["boom"] }).viewports), 2);
  assert.equal(exitCodeFor(verdict({ pageErrors: ["boom"] }).viewports), 2);
});

test("exitCodeFor: navigation failure in any viewport exits 1, beating errors", () => {
  assert.equal(exitCodeFor(verdict({}, { status: 500 }).viewports), 1);
  assert.equal(exitCodeFor(verdict({ status: 0 }).viewports), 1);
  assert.equal(exitCodeFor(verdict({ status: 404 }, { consoleErrors: ["boom"] }).viewports), 1);
});

test("exitCodeFor: 4xx boundary and missing status", () => {
  assert.equal(exitCodeFor(verdict({ status: 399 }).viewports), 0);
  assert.equal(exitCodeFor(verdict({ status: 400 }).viewports), 1);
  assert.equal(exitCodeFor(verdict({ status: undefined }).viewports), 1);
});

test("exitCodeFor: no viewport data is a failure", () => {
  assert.equal(exitCodeFor({}), 1);
  assert.equal(exitCodeFor(undefined), 1);
});

test("browser-smoke wires the guard and verdict helpers", () => {
  const src = readFileSync(join(TEMPLATE_ROOT, "scripts/browser-smoke.mjs"), "utf8");
  assert.match(src, /from "\.\/browser-guard\.mjs"/);
  assert.match(src, /from "\.\/browser-smoke-verdict\.mjs"/);
  assert.match(src, /const args = parseSmokeArgs\(process\.argv\.slice\(2\), process\.env\)/);
  assert.match(src, /const url = checkedUrl\(args\.url\)/);
  assert.match(src, /const outPng = checkedOutputPath\(args\.outPng, \["\/workspace"\]\)/);
  assert.match(src, /const mobilePng = checkedOutputPath\(derived\.mobilePng, \["\/workspace"\]\)/);
  assert.match(src, /const outJson = checkedOutputPath\(derived\.verdictJson, \["\/workspace"\]/);
  assert.match(src, /checkedOutputPath\(realpathSync\(args\.baseline\), \["\/workspace"\]/);
  assert.match(src, /baselinePath === outJson/);
  assert.match(src, /normalizedBodyTextHash\(/);
  assert.match(src, /bodyTextPrefix\(/);
  assert.match(src, /baselineComparison\(/);
  assert.match(src, /process\.exitCode = exitCodeFor\(viewports\)/);
  assert.match(src, /waitUntil: "domcontentloaded"/);
  assert.doesNotMatch(
    src,
    /waitUntil:\s*["']networkidle["']/,
    "Vite HMR never reaches networkidle",
  );
  assert.match(src, /} finally \{\s*await browser\?\.close\(\);/s);
  assert.doesNotMatch(
    src.slice(src.indexOf("let browser = null")),
    /process\.exit\(/,
    "process.exit after Chromium launch skips finally teardown",
  );
});

test("browser-smoke file I/O only touches guarded paths", () => {
  const src = readFileSync(join(TEMPLATE_ROOT, "scripts/browser-smoke.mjs"), "utf8");
  assert.doesNotMatch(src, /(?:writeFileSync|readFileSync|statSync|realpathSync)\(\s*["'`]/);
  const writes = [...src.matchAll(/writeFileSync\(\s*([A-Za-z_$][\w$.]*)/g)].map((m) => m[1]);
  assert.equal(writes.length, 2);
  assert.ok(
    writes.every((v) => v === "outJson"),
    `unexpected writeFileSync target: ${writes}`,
  );
  const reads = [...src.matchAll(/readFileSync\(\s*([A-Za-z_$][\w$.]*)/g)].map((m) => m[1]);
  assert.deepEqual(reads, ["baselinePath"]);
  const stats = [...src.matchAll(/statSync\(\s*([A-Za-z_$][\w$.]*)/g)].map((m) => m[1]);
  assert.deepEqual(stats, ["baselinePath"]);
});

#!/usr/bin/env node
import { mkdirSync, readFileSync, realpathSync, statSync, writeFileSync } from "node:fs";
import { dirname } from "node:path";
import { chromium } from "playwright";
import { checkedOutputPath, checkedUrl } from "./browser-guard.mjs";
import { computeBrandWarnings } from "./brand-check.mjs";
import {
  authInvariantWarnings,
  buildAuthEnabled,
  compareAuthInvariant,
  probeDevAuthEnabled,
} from "./check-auth-invariant.mjs";
import {
  baselineComparison,
  bodyTextPrefix,
  derivedPaths,
  exitCodeFor,
  normalizeBodyText,
  normalizedBodyTextHash,
  parseSmokeArgs,
} from "./browser-smoke-verdict.mjs";

const args = parseSmokeArgs(process.argv.slice(2), process.env);
if (args.error) {
  console.error(JSON.stringify({ ok: false, error: args.error }, null, 2));
  process.exit(1);
}

const url = checkedUrl(args.url);
const outPng = checkedOutputPath(args.outPng, ["/workspace"]);
const derived = derivedPaths(outPng);
const mobilePng = checkedOutputPath(derived.mobilePng, ["/workspace"]);
const outJson = checkedOutputPath(derived.verdictJson, ["/workspace"], "verdict JSON");

const MAX_BASELINE_BYTES = 1024 * 1024;
const baselineRequested = Boolean(args.baseline);
let baselinePath = null;
let baselineResolveError = null;
if (baselineRequested) {
  try {
    baselinePath = checkedOutputPath(realpathSync(args.baseline), ["/workspace"], "baseline");
  } catch (err) {
    baselineResolveError = err?.code ?? "unresolvable path";
  }
  if (baselinePath === outJson) {
    console.error(
      JSON.stringify(
        {
          ok: false,
          error:
            `--baseline ${args.baseline} is this run's own verdict output; ` +
            "pass a distinct output PNG (e.g. app-builder-built.png) so the baseline is not overwritten",
        },
        null,
        2,
      ),
    );
    process.exit(1);
  }
}

const timeoutMs = Number(process.env.BROWSER_SMOKE_TIMEOUT_MS || 45000);

const VIEWPORTS = [
  { name: "desktop", width: 1280, height: 800, screenshot: outPng },
  { name: "mobile", width: 390, height: 844, screenshot: mobilePng },
];

mkdirSync(dirname(outPng), { recursive: true });

function compareAgainstBaseline(verdict) {
  if (!baselinePath) {
    return {
      divergesFromBaseline: true,
      reasons: [`baseline unreadable: ${baselineResolveError ?? "unresolvable path"}`],
    };
  }
  try {
    if (statSync(baselinePath).size > MAX_BASELINE_BYTES) {
      return { divergesFromBaseline: true, reasons: ["baseline unreadable: too large"] };
    }
    return baselineComparison(verdict, readFileSync(baselinePath, "utf8"));
  } catch (err) {
    return {
      divergesFromBaseline: true,
      reasons: [`baseline unreadable: ${err?.code ?? "read error"}`],
    };
  }
}

let browser = null;
try {
  browser = await chromium.launch({
    headless: true,
    args: ["--no-sandbox", "--disable-dev-shm-usage"],
  });

  const viewports = {};
  for (const vp of VIEWPORTS) {
    const errors = { consoleErrors: [], pageErrors: [] };
    const page = await browser.newPage({
      viewport: { width: vp.width, height: vp.height },
    });
    page.on("console", (msg) => {
      if (msg.type() === "error") errors.consoleErrors.push(msg.text());
    });
    page.on("pageerror", (err) => errors.pageErrors.push(String(err?.message || err)));
    // `domcontentloaded`, not `networkidle`: Vite keeps an HMR websocket open, so
    // networkidle never settles and would burn the whole timeout.
    const resp = await page.goto(url, { waitUntil: "domcontentloaded", timeout: timeoutMs });
    const status = resp?.status() ?? 0;
    await page.waitForTimeout(1000);

    const title = await page.title();
    const hasCanvas = (await page.locator("canvas").count()) > 0;
    const bodyText = await page
      .locator("body")
      .innerText()
      .catch(() => "");
    const horizontalOverflow = await page.evaluate(() => {
      const el = document.documentElement;
      return el.scrollWidth > el.clientWidth + 1;
    });
    await page.screenshot({ path: vp.screenshot, fullPage: false });
    await page.close();

    viewports[vp.name] = {
      width: vp.width,
      height: vp.height,
      status,
      title,
      hasCanvas,
      bodyTextLen: normalizeBodyText(bodyText).length,
      bodyTextHash: normalizedBodyTextHash(bodyText),
      bodyTextPrefix: bodyTextPrefix(bodyText),
      horizontalOverflow,
      consoleErrors: errors.consoleErrors,
      pageErrors: errors.pageErrors,
      screenshot: vp.screenshot,
    };
  }

  const brandWarnings = computeBrandWarnings({ hasCanvas: viewports.desktop.hasCanvas });
  // Only a dev server answers /__app-env, so smoking the built output reads as
  // indeterminate — report a divergence, never the absence of an observation.
  const authWarnings = authInvariantWarnings(
    compareAuthInvariant({
      devAuthEnabled: await probeDevAuthEnabled(url),
      buildAuthEnabled: buildAuthEnabled(),
    }),
  );
  const verdict = { url, viewports, brandWarnings, authWarnings, verdictFile: outJson };
  if (baselineRequested) {
    const { divergesFromBaseline, reasons } = compareAgainstBaseline(verdict);
    verdict.divergesFromBaseline = divergesFromBaseline;
    verdict.baselineReasons = reasons;
  }

  writeFileSync(outJson, JSON.stringify(verdict, null, 2));
  console.log(JSON.stringify(verdict, null, 2));
  for (const w of [...brandWarnings, ...authWarnings]) console.error(w);
  // Set the code rather than aborting the process so the `finally` browser
  // teardown always runs (agents typically smoke twice per turn; leaking
  // Chromium accumulates across retries).
  process.exitCode = exitCodeFor(viewports);
} catch (err) {
  const failure = { ok: false, url, error: String(err?.message || err) };
  try {
    writeFileSync(outJson, JSON.stringify(failure, null, 2));
  } catch (writeErr) {
    failure.verdictWriteError = String(writeErr?.message || writeErr);
  }
  console.error(JSON.stringify(failure, null, 2));
  process.exitCode = 1;
} finally {
  await browser?.close();
}

#!/usr/bin/env node
/**
 * Fail loudly when the running dev server and the next build disagree about
 * `VITE_AUTH_ENABLED`.
 *
 * `npm run dev`, `npm run build` and `npm run preview` all get the flag from
 * `scripts/with-app-env.mjs`, so they agree by construction — but a dev server
 * started outside npm (`npx vite dev`) does not, and the result is sign-in
 * visible in the live preview and absent from the built output, or the reverse.
 *
 * The two sides compared:
 *  - **dev**: what the running server resolved, read from the `/__app-env`
 *    endpoint the template's dev-only `appEnvPlugin` serves.
 *  - **build**: what the wrapper hands `vite build` / `vite preview`.
 *
 * The built bundle is not read: Vite inlines the flag and the minifier folds
 * `"false" !== "false"` away, so the built client JS carries no marker to
 * compare against unless the app is made to emit one.
 *
 * `scripts/browser-smoke.mjs` runs the comparison on every smoke; run it
 * standalone against a live dev server with `npm run check:auth` (exit 0 agree,
 * 1 diverged, 2 could not observe). Callers comparing the flag should use
 * `compareAuthInvariant()` rather than re-deriving it.
 */
import { APP_ENV_ROUTE } from "./app-env-plugin.mjs";
import { isMainModule, mergeAppEnv, projectRoot, readAppEnv } from "./with-app-env.mjs";

const DEFAULT_DEV_URL = "http://127.0.0.1:8080";

/** The predicate `src/lib/auth/{client,server}.ts` apply to the flag. */
export function authEnabledFromEnvValue(value) {
  return value !== "false";
}

/**
 * Compare the two resolved values. `null` means "could not observe" — reported
 * as indeterminate rather than as agreement.
 */
export function compareAuthInvariant({ devAuthEnabled, buildAuthEnabled }) {
  const label = (value) => (value ? "on" : "off");
  if (devAuthEnabled === null || devAuthEnabled === undefined) {
    return {
      status: "indeterminate",
      message: "[auth-invariant] could not read the dev server's resolved VITE_AUTH_ENABLED",
    };
  }
  if (devAuthEnabled === buildAuthEnabled) {
    return {
      status: "ok",
      message: `[auth-invariant] dev and build agree: sign-in ${label(devAuthEnabled)}`,
    };
  }
  return {
    status: "diverged",
    message:
      `[auth-invariant] dev server has sign-in ${label(devAuthEnabled)} but the next ` +
      `build has it ${label(buildAuthEnabled)}. Start the app with \`npm run dev\` — ` +
      "invoking vite directly skips scripts/with-app-env.mjs, so the dev server and " +
      "the built output resolve .grok/app-env.json differently.",
  };
}

/**
 * Ask the dev server which env it resolved. Anything but a JSON object from
 * `/__app-env` (no server, a built-output preview, an older workspace without
 * the plugin) is "could not observe".
 */
export async function probeDevAuthEnabled(devUrl, fetchImpl = fetch) {
  let env;
  try {
    const response = await fetchImpl(new URL(APP_ENV_ROUTE, devUrl).href);
    if (!response.ok) return null;
    env = JSON.parse(await response.text());
  } catch {
    return null;
  }
  if (env === null || typeof env !== "object") return null;
  return authEnabledFromEnvValue(env.VITE_AUTH_ENABLED);
}

/** The smoke-verdict warnings for a comparison: a real divergence only. */
export function authInvariantWarnings(result) {
  return result.status === "diverged" ? [result.message] : [];
}

/** What `vite build` / `vite preview` will resolve, via the same wrapper. */
export function buildAuthEnabled(root = projectRoot(), processEnv = process.env) {
  const env = mergeAppEnv(readAppEnv(root), processEnv);
  return authEnabledFromEnvValue(env.VITE_AUTH_ENABLED);
}

async function main(argv) {
  const devUrlFlag = argv.indexOf("--dev-url");
  const devUrl = devUrlFlag === -1 ? DEFAULT_DEV_URL : argv[devUrlFlag + 1];
  const result = compareAuthInvariant({
    devAuthEnabled: await probeDevAuthEnabled(devUrl),
    buildAuthEnabled: buildAuthEnabled(),
  });
  if (result.status === "ok") {
    console.log(result.message);
    process.exit(0);
  }
  console.error(result.message);
  process.exit(result.status === "diverged" ? 1 : 2);
}

if (isMainModule(import.meta.url)) {
  await main(process.argv.slice(2));
}

import assert from "node:assert/strict";
import { execFile } from "node:child_process";
import { mkdtempSync, symlinkSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { test } from "node:test";
import { promisify } from "node:util";
import {
  authEnabledFromEnvValue,
  authInvariantWarnings,
  buildAuthEnabled,
  compareAuthInvariant,
  probeDevAuthEnabled,
} from "./check-auth-invariant.mjs";
import { projectRoot } from "./with-app-env.mjs";

/**
 * The JSON body `/__app-env` would serve. Do not start a real Vite server —
 * `import { createServer } from "vite"` loads rolldown native bindings that
 * SIGSEGV the test worker under qemu-user (amd64 image builds).
 */
function appEnvFetch(env) {
  return async () => ({
    ok: true,
    text: async () => JSON.stringify(env),
  });
}

test("the flag predicate matches src/lib/auth", () => {
  assert.equal(authEnabledFromEnvValue("false"), false);
  assert.equal(authEnabledFromEnvValue("true"), true);
  assert.equal(authEnabledFromEnvValue(undefined), true);
});

test("reads the value a live dev server resolved", async () => {
  assert.equal(
    await probeDevAuthEnabled("http://127.0.0.1:8080", appEnvFetch({ VITE_AUTH_ENABLED: "false" })),
    false,
  );
});

test("a server started without the flag reads as sign-in on", async () => {
  assert.equal(await probeDevAuthEnabled("http://127.0.0.1:8080", appEnvFetch({})), true);
});

test("agreement passes", () => {
  assert.equal(
    compareAuthInvariant({ devAuthEnabled: false, buildAuthEnabled: false }).status,
    "ok",
  );
});

test("divergence fails in either direction", () => {
  const devOn = compareAuthInvariant({ devAuthEnabled: true, buildAuthEnabled: false });
  assert.equal(devOn.status, "diverged");
  assert.match(devOn.message, /dev server has sign-in on but the next build has it off/);
  assert.equal(
    compareAuthInvariant({ devAuthEnabled: false, buildAuthEnabled: true }).status,
    "diverged",
  );
});

test("an unobservable dev server is indeterminate, not agreement", () => {
  assert.equal(
    compareAuthInvariant({ devAuthEnabled: null, buildAuthEnabled: false }).status,
    "indeterminate",
  );
});

test("a dev server that cannot be reached probes as null", async () => {
  const unreachable = () => Promise.reject(new Error("ECONNREFUSED"));
  assert.equal(await probeDevAuthEnabled("http://127.0.0.1:1", unreachable), null);
});

test("a server without the endpoint probes as null, not as agreement", async () => {
  const notFound = async () => ({ ok: false, text: async () => "Not Found" });
  assert.equal(await probeDevAuthEnabled("http://127.0.0.1:8081", notFound), null);
  const html = async () => ({ ok: true, text: async () => "<!doctype html>" });
  assert.equal(await probeDevAuthEnabled("http://127.0.0.1:8081", html), null);
});

test("only a divergence warns the smoke verdict", () => {
  const diverged = compareAuthInvariant({ devAuthEnabled: true, buildAuthEnabled: false });
  assert.deepEqual(authInvariantWarnings(diverged), [diverged.message]);
  for (const result of [
    compareAuthInvariant({ devAuthEnabled: false, buildAuthEnabled: false }),
    compareAuthInvariant({ devAuthEnabled: null, buildAuthEnabled: false }),
  ]) {
    assert.deepEqual(authInvariantWarnings(result), []);
  }
});

test("the build side resolves the template's shipped app-env", () => {
  assert.equal(buildAuthEnabled(projectRoot(), {}), false);
  assert.equal(buildAuthEnabled(projectRoot(), { VITE_AUTH_ENABLED: "true" }), true);
});

test("the CLI reports rather than silently passing when run via a symlink", async () => {
  // A check whose exit code is the whole signal must never no-op to 0 because
  // process.argv[1] came in through a symlinked path.
  const link = join(mkdtempSync(join(tmpdir(), "auth-invariant-link-")), "scripts");
  symlinkSync(join(projectRoot(), "scripts"), link);
  const error = await promisify(execFile)(process.execPath, [
    join(link, "check-auth-invariant.mjs"),
    "--dev-url",
    "http://127.0.0.1:1",
  ]).catch((err) => err);
  assert.equal(error.code, 2);
  assert.match(error.stderr, /could not read the dev server's resolved VITE_AUTH_ENABLED/);
});

