#!/usr/bin/env node
/**
 * Run a command with `.grok/app-env.json` merged into its environment.
 *
 * `dev`, `build` and `preview` all route through this wrapper, so the dev
 * server, the built bundle and the preview server can never disagree about
 * `VITE_AUTH_ENABLED` — a divergence that only shows up as a built-output
 * mismatch long after the fact. Anything that starts Vite directly bypasses it.
 *
 * Only `VITE_`-prefixed keys are honored: the file is a build flag carrier, not
 * a secret store, and only `VITE_` vars reach the browser anyway. A real
 * `process.env` entry always wins, so an explicit override still works.
 *
 * That precedence also means the file governs this workspace only. A deployed
 * build runs with the provider's project env, where the deployer sets
 * `VITE_AUTH_ENABLED` itself (today unconditionally `"true"`), so the deployed
 * flag is the platform's, not this file's.
 *
 * Vite picks the values up because `loadEnv` prefix-matches entries already in
 * `process.env`, which is why the merge has to happen before Vite starts.
 */
import { spawn } from "node:child_process";
import { readFileSync, realpathSync } from "node:fs";
import { constants as osConstants } from "node:os";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

export const APP_ENV_REL_PATH = ".grok/app-env.json";

const VITE_PREFIX = "VITE_";

/**
 * Parse an app-env document, keeping only `VITE_`-prefixed string entries.
 * Anything unparseable is an empty environment — a workspace without the file
 * must behave exactly like today (auth on, no overrides).
 */
export function parseAppEnv(text) {
  let parsed;
  try {
    parsed = JSON.parse(text);
  } catch {
    return {};
  }
  if (parsed === null || typeof parsed !== "object" || Array.isArray(parsed)) return {};
  const env = {};
  for (const [key, value] of Object.entries(parsed)) {
    if (!key.startsWith(VITE_PREFIX)) continue;
    if (typeof value !== "string") continue;
    env[key] = value;
  }
  return env;
}

/** The app env recorded under `root`, or `{}` when the file is absent. */
export function readAppEnv(root) {
  try {
    return parseAppEnv(readFileSync(join(root, APP_ENV_REL_PATH), "utf8"));
  } catch {
    return {};
  }
}

/** File values under the process environment: an explicit override wins. */
export function mergeAppEnv(appEnv, processEnv) {
  return { ...appEnv, ...processEnv };
}

/**
 * Translate a child's `exit` `(code, signal)` into this process's exit status.
 *
 * Do not re-raise the signal with `process.kill(process.pid, signal)`: under
 * qemu-user (amd64 image builds on an arm host) a self-directed signal is
 * routinely delivered as SIGSEGV to the wrong process, which takes down the
 * test worker and fails the image build. `128 + signo` is what a shell reports
 * for a signal-killed command, so a cancelled `vite build` is still a failure.
 */
export function exitStatusFromChild(code, signal) {
  if (signal) {
    const signo = osConstants.signals[signal];
    return 128 + (typeof signo === "number" ? signo : 1);
  }
  return code ?? 1;
}

/** The workspace root (this file lives in `<root>/scripts/`). */
export function projectRoot() {
  return dirname(dirname(fileURLToPath(import.meta.url)));
}

/**
 * Whether `moduleUrl` is the script node was asked to run.
 *
 * Both sides are resolved through symlinks: node realpaths `import.meta.url`
 * but leaves `process.argv[1]` as typed, so comparing them raw makes a CLI
 * launched through a symlinked path (`/tmp` on macOS) a silent no-op.
 */
export function isMainModule(moduleUrl) {
  const entry = process.argv[1];
  if (!entry) return false;
  try {
    return realpathSync(entry) === fileURLToPath(moduleUrl);
  } catch {
    return false;
  }
}

function main(argv) {
  const [command, ...args] = argv;
  if (!command) {
    console.error("usage: node scripts/with-app-env.mjs <command> [args…]");
    process.exit(2);
  }
  const env = mergeAppEnv(readAppEnv(projectRoot()), process.env);
  const child = spawn(command, args, { stdio: "inherit", env });
  // The dev server is long-running and is stopped by signalling this wrapper.
  for (const signal of ["SIGINT", "SIGTERM", "SIGHUP"]) {
    process.on(signal, () => child.kill(signal));
  }
  child.on("error", (err) => {
    console.error(`[with-app-env] failed to run ${command}:`, err?.message || err);
    process.exit(127);
  });
  child.on("exit", (code, signal) => {
    process.exit(exitStatusFromChild(code, signal));
  });
}

if (isMainModule(import.meta.url)) {
  main(process.argv.slice(2));
}

import assert from "node:assert/strict";
import { execFile } from "node:child_process";
import { mkdirSync, mkdtempSync, symlinkSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { test } from "node:test";
import { promisify } from "node:util";
import {
  APP_ENV_REL_PATH,
  mergeAppEnv,
  parseAppEnv,
  projectRoot,
  readAppEnv,
} from "./with-app-env.mjs";

const execFileAsync = promisify(execFile);
const WRAPPER = join(projectRoot(), "scripts/with-app-env.mjs");
const PRINT_FLAG = "process.stdout.write(String(process.env.VITE_AUTH_ENABLED));";

function makeWorkspace(appEnvJson) {
  const root = mkdtempSync(join(tmpdir(), "app-env-"));
  if (appEnvJson !== undefined) {
    mkdirSync(join(root, ".grok"), { recursive: true });
    writeFileSync(join(root, APP_ENV_REL_PATH), appEnvJson);
  }
  return root;
}

test("keeps VITE_-prefixed string entries", () => {
  assert.deepEqual(parseAppEnv('{"VITE_AUTH_ENABLED":"false"}'), {
    VITE_AUTH_ENABLED: "false",
  });
});

test("drops non-VITE keys, non-string values and malformed documents", () => {
  assert.deepEqual(parseAppEnv('{"DATABASE_URL":"postgres://x","VITE_N":1,"VITE_OK":"y"}'), {
    VITE_OK: "y",
  });
  assert.deepEqual(parseAppEnv("not json"), {});
  assert.deepEqual(parseAppEnv('["VITE_AUTH_ENABLED"]'), {});
  assert.deepEqual(parseAppEnv("null"), {});
});

test("a missing app-env.json is a clean no-op", () => {
  assert.deepEqual(readAppEnv(makeWorkspace()), {});
});

test("reads the app env from a workspace", () => {
  const root = makeWorkspace('{"VITE_AUTH_ENABLED":"false"}');
  assert.deepEqual(readAppEnv(root), { VITE_AUTH_ENABLED: "false" });
});

test("an explicit process-env override wins over the file", () => {
  const merged = mergeAppEnv(
    { VITE_AUTH_ENABLED: "false" },
    { VITE_AUTH_ENABLED: "true", PATH: "/usr/bin" },
  );
  assert.equal(merged.VITE_AUTH_ENABLED, "true");
  assert.equal(merged.PATH, "/usr/bin");
});

test("the template ships auth off", () => {
  assert.deepEqual(readAppEnv(projectRoot()), { VITE_AUTH_ENABLED: "false" });
});

test("vite loadEnv resolves the wrapped value", () => {
  // What `import.meta.env.VITE_AUTH_ENABLED` becomes: loadEnv prefix-matches
  // process.env, so the wrapper's merge has to land before Vite starts.
  // Do not `import { loadEnv } from "vite"` here — Vite 8 loads rolldown
  // native bindings that SIGSEGV the test worker under qemu-user.
  const root = makeWorkspace('{"VITE_AUTH_ENABLED":"false"}');
  const merged = mergeAppEnv(readAppEnv(root), { PATH: "/usr/bin" });
  assert.equal(merged.VITE_AUTH_ENABLED, "false");
});

test("the wrapped command runs with the app env applied", async () => {
  const { stdout } = await execFileAsync(process.execPath, [
    WRAPPER,
    process.execPath,
    "-e",
    PRINT_FLAG,
  ]);
  assert.equal(stdout, "false");
});

test("the wrapped command sees an explicit override, not the file value", async () => {
  const { stdout } = await execFileAsync(
    process.execPath,
    [WRAPPER, process.execPath, "-e", PRINT_FLAG],
    { env: { ...process.env, VITE_AUTH_ENABLED: "true" } },
  );
  assert.equal(stdout, "true");
});

test("the wrapper propagates the command's exit code", async () => {
  await assert.rejects(
    execFileAsync(process.execPath, [WRAPPER, process.execPath, "-e", "process.exit(3)"]),
    (err) => err.code === 3,
  );
});

test("a signal-killed command is never reported as success", async () => {
  // The wrapper's own SIGTERM handler must not swallow the re-raised signal:
  // a cancelled build reporting exit 0 is a silently passing gate.
  await assert.rejects(
    execFileAsync(process.execPath, [
      WRAPPER,
      process.execPath,
      "-e",
      "process.kill(process.pid, 'SIGTERM');setTimeout(() => {}, 1000);",
    ]),
    (err) => err.signal === "SIGTERM" || err.code !== 0,
  );
});

test("the CLI still runs when invoked through a symlinked path", async () => {
  // node realpaths import.meta.url but not process.argv[1], so a raw comparison
  // turns the wrapper into a no-op that exits 0 without starting anything.
  const link = join(mkdtempSync(join(tmpdir(), "app-env-link-")), "scripts");
  symlinkSync(join(projectRoot(), "scripts"), link);
  const { stdout } = await execFileAsync(process.execPath, [
    join(link, "with-app-env.mjs"),
    process.execPath,
    "-e",
    PRINT_FLAG,
  ]);
  assert.equal(stdout, "false");
});

/**
 * Serves the Minha Jornada install identity on the platform manifest URL.
 * Must run before grok-pwa.ts (filename sorts first) so custom-domain
 * installs are not labeled "Grok App" with the black default icon.
 */
import { APP_MANIFEST_BODY, isAppManifestPath } from "../../scripts/app-manifest.mjs";

interface AppManifestEvent {
  url: URL;
  req: { method: string };
}

export default async function appManifestMiddleware(
  event: AppManifestEvent,
  next: () => unknown | Promise<unknown>,
): Promise<unknown> {
  const method = (event.req.method ?? "GET").toUpperCase();
  if (method === "GET" && isAppManifestPath(event.url.pathname)) {
    return new Response(APP_MANIFEST_BODY, {
      headers: {
        "content-type": "application/manifest+json; charset=utf-8",
        "cache-control": "no-store",
      },
    });
  }
  return next();
}

/**
 * Deployed-app (Nitro) half of the platform PWA chrome. Auto-registered as
 * global h3 middleware because vite.config.ts sets `serverDir: "./server"` —
 * without that option Nitro v3 never scans this directory.
 *
 * - `?install=1&platform=ios` on a document path → the Home Screen tutorial,
 *   bundled into the server build via `?raw` (the public/ directory is CDN
 *   static output on Vercel and not readable from the function).
 * - `/__grok/manifest.webmanifest` → per-app-named manifest (kept out of
 *   public/ so this dynamic response is the only one).
 * - Other HTML documents → stream-inject PWA + OG head tags at `</head>`.
 *   OG identity is baked via `virtual:grok-og-identity` at `vite build`
 *   (this function cannot read `src/lib/og/site.json` or `public/og.jpg`).
 *   This must be a middleware transforming `next()`: h3 discards the `response`
 *   runtime hook's return value, and `render:html` does not exist in Nitro v3.
 */
import installPageTemplate from "../../scripts/install-page.html?raw";
import { grokOgIdentity } from "virtual:grok-og-identity";
import {
  acceptsHtml,
  createHeadInjector,
  isDocumentPath,
  isInstallQuery,
  renderInstallPageHtml,
  renderWebManifest,
} from "../../scripts/grok-pwa-shared.mjs";

interface GrokPwaEvent {
  url: URL;
  req: { method: string; headers: Headers };
}

function requestHost(event: GrokPwaEvent): string {
  return (
    event.req.headers.get("x-forwarded-host") ?? event.req.headers.get("host") ?? event.url.host
  );
}

function injectHeadStreaming(response: Response, host: string): Response {
  const injector = createHeadInjector({
    host,
    site: grokOgIdentity.site,
  });
  const transformed = response.body!.pipeThrough(
    new TransformStream<Uint8Array, Uint8Array>({
      transform(chunk, controller) {
        for (const out of injector.push(chunk)) controller.enqueue(out);
      },
      flush(controller) {
        for (const out of injector.flush()) controller.enqueue(out);
      },
    }),
  );
  const headers = new Headers(response.headers);
  headers.delete("content-length");
  return new Response(transformed, {
    status: response.status,
    statusText: response.statusText,
    headers,
  });
}

export default async function grokPwaMiddleware(
  event: GrokPwaEvent,
  next: () => unknown | Promise<unknown>,
): Promise<unknown> {
  const method = (event.req.method ?? "GET").toUpperCase();
  if (method !== "GET") return next();

  const path = event.url.pathname;
  const urlWithQuery = path + event.url.search;

  if (path === "/__grok/manifest.webmanifest" || path === "/__grok/manifest.json") {
    return new Response(renderWebManifest(requestHost(event)), {
      headers: {
        "content-type": "application/manifest+json; charset=utf-8",
        "cache-control": "no-cache",
      },
    });
  }

  if (
    isInstallQuery(urlWithQuery) &&
    isDocumentPath(path) &&
    acceptsHtml(event.req.headers.get("accept"))
  ) {
    const html = renderInstallPageHtml(installPageTemplate, {
      host: requestHost(event),
      url: urlWithQuery,
    });
    return new Response(html, {
      headers: {
        "content-type": "text/html; charset=utf-8",
        "cache-control": "no-cache",
      },
    });
  }

  if (!isDocumentPath(path)) return next();

  const result = await next();
  if (
    result instanceof Response &&
    result.body &&
    String(result.headers.get("content-type") ?? "").includes("text/html") &&
    !result.headers.get("content-encoding")
  ) {
    return injectHeadStreaming(result, requestHost(event));
  }
  return result;
}

declare module "virtual:grok-og-identity" {
  export const grokOgIdentity: {
    site: {
      title?: string;
      description?: string;
      type?: string;
      card?: string;
      image?: string;
      banner?: string;
      color?: string;
    };
  };
}

import { useEffect } from "react";
import { BellRing } from "lucide-react";
import { Button } from "@/components/ui/button";
import { useJournal } from "@/lib/journal-store";

export function AlertFeed({ journeyOnly = false }: { journeyOnly?: boolean }) {
  const alerts = useJournal((s) => s.alerts);
  const journeyId = useJournal((s) => s.journeyId);
  const refresh = useJournal((s) => s.refreshAlerts);
  const markRead = useJournal((s) => s.markAlertsRead);
  const openPatient = useJournal((s) => s.openPatient);

  useEffect(() => {
    void refresh();
    const id = window.setInterval(() => void refresh(), 60_000);
    return () => window.clearInterval(id);
  }, [refresh]);

  const visible = journeyOnly && journeyId
    ? alerts.filter((alert) => alert.journeyId === journeyId)
    : alerts;
  const unread = visible.filter((alert) => !alert.read).length;

  if (!visible.length) {
    return (
      <section className="rounded-xl bg-card p-5 shadow-[var(--shadow-border)]">
        <h2 className="flex items-center gap-2 font-display text-lg font-semibold">
          <BellRing className="size-4 text-primary" />
          Alertas
        </h2>
        <p className="mt-2 text-sm text-muted-foreground">
          Nenhuma regra configurada foi acionada nos registros exibidos.
        </p>
      </section>
    );
  }

  return (
    <section className="rounded-xl bg-card p-5 shadow-[var(--shadow-border)]">
      <div className="mb-3 flex items-center justify-between gap-3">
        <div>
          <h2 className="flex items-center gap-2 font-display text-lg font-semibold">
            <BellRing className="size-4 text-primary" />
            Alertas
            {unread > 0 && (
              <span className="rounded-full bg-primary px-2 py-0.5 text-xs text-primary-foreground">
                {unread}
              </span>
            )}
          </h2>
          <p className="mt-1 text-xs text-muted-foreground">
            Apenas regras publicadas e configuradas pela médica.
          </p>
        </div>
        {unread > 0 && (
          <Button
            type="button"
            variant="ghost"
            size="sm"
            onClick={() => void markRead(visible.filter((item) => !item.read).map((item) => item.id))}
          >
            Marcar lidos
          </Button>
        )}
      </div>

      <ul className="space-y-2">
        {visible.slice(0, 12).map((alert) => (
          <li key={alert.id}>
            <button
              type="button"
              className="w-full rounded-lg border border-border/60 px-3 py-3 text-left hover:bg-secondary"
              onClick={() => {
                if (!alert.read) void markRead([alert.id]);
                if (!journeyOnly) void openPatient(alert.journeyId);
              }}
            >
              <div className="flex items-start justify-between gap-3">
                <div>
                  <p className="text-sm font-medium">
                    {!alert.read && (
                      <span className="mr-2 inline-block size-2 rounded-full bg-primary align-middle" />
                    )}
                    {alert.patientName}
                  </p>
                  <p className="mt-1 text-sm leading-relaxed">{alert.title}</p>
                  <p className="mt-1 text-xs text-muted-foreground">
                    {alert.moduleTitle} · registro de {alert.occurredOn.split("-").reverse().join("/")}
                  </p>
                </div>
                <span
                  className={
                    alert.severity === "important"
                      ? "rounded-md bg-warn px-2 py-1 text-[11px] font-medium text-warn-foreground"
                      : "rounded-md bg-secondary px-2 py-1 text-[11px] font-medium"
                  }
                >
                  {alert.severity === "important" ? "Importante" : "Atenção"}
                </span>
              </div>
            </button>
          </li>
        ))}
      </ul>
    </section>
  );
}

import { Link, useRouterState } from "@tanstack/react-router";
import { CalendarDays, ClipboardCheck, House, Route, UserRound } from "lucide-react";
import { type ReactNode, useEffect, useState } from "react";
import { CodeEntry } from "@/components/code-entry";
import { DoctorDesk } from "@/components/doctor-desk";
import { LogoLockup } from "@/components/logo";
import { Onboarding } from "@/components/onboarding";
import { RoleSetup } from "@/components/role-setup";
import { Button } from "@/components/ui/button";
import { logOut } from "@/lib/logout";
import { RedirectToSignIn } from "@/lib/auth/gates";
import { useCurrentUserState } from "@/lib/auth/use-current-user";
import { useJournal } from "@/lib/journal-store";
import { cn } from "@/lib/utils";

const NAV_PATIENT = [
  { to: "/", label: "Início", icon: House },
  { to: "/hoje", label: "Hoje", icon: ClipboardCheck },
  { to: "/mes", label: "Evolução", icon: CalendarDays },
  { to: "/jornada", label: "Jornada", icon: Route },
  { to: "/pendencias", label: "Pendências", icon: ClipboardCheck },
] as const;

const NAV_DOCTOR = [
  { to: "/", label: "Início", icon: House },
  { to: "/mes", label: "Registros", icon: ClipboardCheck },
  { to: "/jornada", label: "Jornada", icon: Route },
  { to: "/pendencias", label: "Pendências", icon: CalendarDays },
  { to: "/perfil", label: "Perfil", icon: UserRound },
] as const;

export function AppShell({ children }: { children: ReactNode }) {
  const pathname = useRouterState({ select: (s) => s.location.pathname });
  const { user, isPending } = useCurrentUserState();
  const ready = useJournal((s) => s.ready);
  const role = useJournal((s) => s.role);
  const onboarded = useJournal((s) => s.onboarded);
  const journeyId = useJournal((s) => s.journeyId);
  const hydrate = useJournal((s) => s.hydrate);
  const clear = useJournal((s) => s.clear);
  const [bootError, setBootError] = useState<string | null>(null);

  useEffect(() => {
    if (!user) {
      clear();
      setBootError(null);
      return;
    }
    setBootError(null);
    void hydrate().catch((err: unknown) => {
      setBootError(err instanceof Error ? err.message : "Não foi possível carregar a jornada.");
    });
  }, [user?.id, hydrate, clear]);

  if (pathname === "/login") {
    return <>{children}</>;
  }

  if (isPending) {
    return <BootScreen label="Carregando sua sessão…" />;
  }
  if (!user) return <RedirectToSignIn />;
  if (bootError) {
    return (
      <BootScreen label={bootError}>
        <Button
          type="button"
          className="mt-3"
          onClick={() => {
            setBootError(null);
            void hydrate().catch((err: unknown) => {
              setBootError(
                err instanceof Error ? err.message : "Não foi possível carregar a jornada.",
              );
            });
          }}
        >
          Tentar de novo
        </Button>
      </BootScreen>
    );
  }
  if (!ready) return <BootScreen label="Carregando sua jornada…" />;
  if (!role) return <RoleSetup />;
  if (role === "doctor" && !journeyId) return <DoctorDesk />;
  if (role === "patient" && !journeyId) return <CodeEntry />;
  if (!onboarded && role === "patient") return <Onboarding />;

  const nav = role === "doctor" ? NAV_DOCTOR : NAV_PATIENT;

  return (
    <div className="mx-auto flex min-h-dvh w-full max-w-lg md:max-w-5xl">
      <aside className="sticky top-0 hidden h-dvh w-56 shrink-0 flex-col border-r border-border/70 bg-card/60 px-3 py-5 md:flex">
        <LogoLockup />
        <nav className="mt-8 flex flex-col gap-1" aria-label="Principal">
          {nav.map((item) => (
            <NavLink key={item.to} {...item} active={pathname === item.to} />
          ))}
        </nav>
        <AccountChip className="mt-auto" />
      </aside>

      <div className="flex min-w-0 flex-1 flex-col">
        <header className="sticky top-0 z-30 flex items-center justify-between gap-3 border-b border-border/70 bg-background/90 px-4 py-3 backdrop-blur-md">
          <div className="md:hidden">
            <LogoLockup />
          </div>
          <SharingBanner />
          <HeaderSignOut />
          <AccountChip className="ml-auto hidden sm:flex md:hidden" />
        </header>
        <main className="flex-1 px-4 pb-28 pt-4 md:px-8 md:pb-10 md:pt-8">{children}</main>
        <nav
          className="fixed inset-x-0 bottom-0 z-40 border-t border-border/80 bg-card/95 pb-[max(0.5rem,env(safe-area-inset-bottom))] backdrop-blur-md md:hidden"
          aria-label="Principal"
        >
          <ul className="mx-auto grid max-w-lg grid-cols-5 px-1 pt-1">
            {nav.map((item) => {
              const active = pathname === item.to;
              const Icon = item.icon;
              return (
                <li key={item.to}>
                  <Link
                    to={item.to}
                    className={cn(
                      "flex min-h-14 flex-col items-center justify-center gap-0.5 rounded-lg text-[11px] font-medium transition-colors",
                      active ? "text-primary" : "text-muted-foreground hover:text-foreground",
                    )}
                  >
                    <Icon className="size-5" strokeWidth={active ? 2.2 : 1.8} />
                    {item.label}
                  </Link>
                </li>
              );
            })}
          </ul>
        </nav>
      </div>
    </div>
  );
}

function NavLink({
  to,
  label,
  icon: Icon,
  active,
}: {
  to: string;
  label: string;
  icon: (typeof NAV_PATIENT)[number]["icon"];
  active: boolean;
}) {
  return (
    <Link
      to={to}
      className={cn(
        "flex min-h-11 items-center gap-3 rounded-lg px-3 text-sm font-medium transition-colors",
        active
          ? "bg-accent text-accent-foreground"
          : "text-muted-foreground hover:bg-secondary hover:text-foreground",
      )}
    >
      <Icon className="size-4" strokeWidth={active ? 2.2 : 1.8} />
      {label}
    </Link>
  );
}

function BootScreen({ label, children }: { label: string; children?: ReactNode }) {
  return (
    <div className="flex min-h-dvh items-center justify-center px-6">
      <div className="flex flex-col items-center gap-3 text-center text-muted-foreground">
        <LogoLockup />
        <span className="text-sm">{label}</span>
        {children}
      </div>
    </div>
  );
}

function HeaderSignOut() {
  const [busy, setBusy] = useState(false);
  return (
    <button
      type="button"
      disabled={busy}
      className="shrink-0 text-xs font-medium text-muted-foreground underline-offset-4 hover:underline disabled:opacity-60 md:hidden"
      onClick={() => {
        setBusy(true);
        void logOut().catch(() => setBusy(false));
      }}
    >
      {busy ? "Saindo…" : "Sair"}
    </button>
  );
}

function SharingBanner() {
  const role = useJournal((s) => s.role);
  const inviteCode = useJournal((s) => s.inviteCode);
  const doctorName = useJournal((s) => s.doctorName);
  const patientName = useJournal((s) => s.patientName);
  const leavePatient = useJournal((s) => s.leavePatient);

  if (role === "doctor") {
    return (
      <div className="min-w-0 flex-1">
        <p className="truncate text-sm font-medium">{patientName || "Paciente"}</p>
        <button type="button" className="text-xs text-primary" onClick={() => leavePatient()}>
          Trocar paciente
        </button>
      </div>
    );
  }

  if (!inviteCode) return <div className="flex-1" />;
  return (
    <div className="min-w-0 flex-1">
      <p className="truncate text-xs text-muted-foreground">
        {doctorName ? `Acompanhamento com ${doctorName}` : "Seu plano"}
      </p>
    </div>
  );
}

function AccountChip({ className }: { className?: string }) {
  const { user } = useCurrentUserState();
  const [busy, setBusy] = useState(false);
  if (!user) {
    return <div className={cn("h-8 w-8 animate-pulse rounded-full bg-secondary", className)} />;
  }
  const label = user.displayName ?? user.primaryEmail ?? "Conta";
  return (
    <div className={cn("flex items-center gap-2", className)}>
      {user.profileImageUrl ? (
        <img src={user.profileImageUrl} alt="" className="size-8 rounded-full object-cover" />
      ) : (
        <span className="grid size-8 place-items-center rounded-full bg-secondary text-xs font-medium">
          {label.charAt(0).toUpperCase()}
        </span>
      )}
      <button
        type="button"
        disabled={busy}
        className="text-xs text-muted-foreground underline-offset-4 hover:underline disabled:opacity-60"
        onClick={() => {
          setBusy(true);
          void logOut().catch(() => setBusy(false));
        }}
      >
        {busy ? "Saindo…" : "Sair"}
      </button>
    </div>
  );
}

import { useNavigate } from "@tanstack/react-router";
import { useState } from "react";
import { LogoMark } from "@/components/logo";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { SignOutButton } from "@/components/sign-out-button";
import { CLINIC_NAME } from "@/lib/constants";
import { useJournal } from "@/lib/journal-store";

export function CodeEntry() {
  const claimCode = useJournal((s) => s.claimCode);
  const patientName = useJournal((s) => s.patientName);
  const navigate = useNavigate();
  const [code, setCode] = useState("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);

  return (
    <div className="mx-auto flex min-h-dvh w-full max-w-lg flex-col px-5 py-8">
      <LogoMark className="size-16 rounded-[1.25rem]" />
      <p className="mt-5 text-[11px] font-semibold uppercase tracking-[0.22em] text-primary">
        {CLINIC_NAME}
      </p>
      <h1 className="mt-2 font-display text-3xl font-semibold tracking-tight">
        {patientName ? `Olá, ${patientName.split(" ")[0]}` : "Entre com o código"}
      </h1>
      <p className="mt-2 text-sm leading-relaxed text-muted-foreground">
        A médica envia o código do seu plano. Depois de incluir, você vai
        direto para a jornada.
      </p>
      <form
        className="mt-6 space-y-4"
        onSubmit={(e) => {
          e.preventDefault();
          setBusy(true);
          setError(null);
          void claimCode(code)
            .then(() => navigate({ to: "/jornada" }))
            .catch((err: unknown) => {
              setError(err instanceof Error ? err.message : "Código inválido.");
              setBusy(false);
            });
        }}
      >
        <div className="space-y-1.5">
          <Label htmlFor="plan-code">Código do plano</Label>
          <Input
            id="plan-code"
            value={code}
            onChange={(e) => setCode(e.target.value.toUpperCase())}
            placeholder="Ex.: 7K2M9P"
            className="tracking-[0.2em]"
            autoCapitalize="characters"
            required
          />
        </div>
        {error && <p className="text-sm text-destructive">{error}</p>}
        <Button type="submit" className="w-full" disabled={busy || code.trim().length < 6}>
          {busy ? "Abrindo jornada…" : "Entrar na jornada"}
        </Button>
      </form>
      <SignOutButton variant="ghost" className="mt-auto w-full" />
    </div>
  );
}

import type { LucideIcon } from "lucide-react";
import { Droplets, Footprints, Moon, Salad, Sparkles, Users } from "lucide-react";
import type { ReactNode } from "react";
import { AEROBIC_OPTIONS, STRENGTH_OPTIONS, SYMPTOMS } from "@/lib/constants";
import { isInjectionDay } from "@/lib/calendar";
import { useJournal } from "@/lib/journal-store";
import type { AerobicKind, DayLog, MealsStatus, SocialStatus, SymptomCode, SymptomEntry } from "@/lib/types";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";

type Props = {
  dateKey: string;
  date: Date;
};

const EMPTY_LOG: DayLog = {};

export function DayEditor({ dateKey, date }: Props) {
  const log = useJournal((s) => s.days[dateKey]) ?? EMPTY_LOG;
  const patch = useJournal((s) => s.patchDay);
  const weekday = useJournal((s) => s.profile.injectionWeekday);
  const plan = useJournal((s) => s.plan);
  const inj = isInjectionDay(date, weekday);
  const symptoms = SYMPTOMS.filter((s) => plan.medication.symptoms.includes(s.code));

  return (
    <div className="space-y-5">
      {plan.medication.enabled && (
        <Section icon={Droplets} title="Medicação e efeitos">
          {plan.medication.hasInjection && inj && (
            <p className="mb-3 rounded-md bg-accent px-3 py-2 text-xs text-accent-foreground">
              Dia fixo da aplicação.
            </p>
          )}
          {plan.medication.hasInjection && (
            <ToggleRow
              label="Apliquei hoje"
              on={Boolean(log.applied)}
              onToggle={() => patch(dateKey, { applied: !log.applied })}
            />
          )}
          <p className="mt-4 mb-2 text-xs font-medium text-muted-foreground">
            Sintomas · intensidade 0 a 3
          </p>
          <div className="flex flex-col gap-2">
            {symptoms.map((s) => {
              const current = log.symptoms?.find((x) => x.code === s.code);
              const active = Boolean(current);
              return (
                <div key={s.code} className="flex items-center gap-2">
                  <button
                    type="button"
                    onClick={() => patch(dateKey, { symptoms: toggleSymptom(log, s.code) })}
                    className={cn(
                      "flex h-10 min-w-14 items-center justify-center rounded-md text-xs font-semibold",
                      active ? "bg-primary text-primary-foreground" : "bg-secondary text-secondary-foreground",
                    )}
                  >
                    {s.code}
                  </button>
                  <span className="flex-1 text-sm">{s.label}</span>
                  {s.code !== "S" && (
                    <div className="flex gap-1">
                      {[1, 2, 3].map((n) => (
                        <button
                          key={n}
                          type="button"
                          onClick={() => patch(dateKey, { symptoms: setIntensity(log, s.code, n) })}
                          className={cn(
                            "size-9 rounded-md text-xs font-semibold tabular-nums",
                            current?.intensity === n
                              ? "bg-primary text-primary-foreground"
                              : "bg-secondary text-muted-foreground",
                          )}
                        >
                          {n}
                        </button>
                      ))}
                    </div>
                  )}
                </div>
              );
            })}
          </div>
          {log.symptoms?.some((s) => s.code === "O") && (
            <div className="mt-3 space-y-1.5">
              <Label htmlFor="other">Descreva o outro sintoma</Label>
              <Input
                id="other"
                value={log.otherNote ?? ""}
                onChange={(e) => patch(dateKey, { otherNote: e.target.value })}
              />
            </div>
          )}
        </Section>
      )}

      {plan.movement.enabled && (
        <Section icon={Footprints} title="Movimento">
          {plan.movement.aerobic.map((kind) => (
            <MinutesRow
              key={kind}
              label={AEROBIC_OPTIONS.find((o) => o.id === kind)?.label ?? kind}
              value={minutesFor(log, kind)}
              onChange={(n) => patch(dateKey, { aerobic: { ...(log.aerobic ?? {}), [kind]: n } })}
            />
          ))}
          {plan.movement.strength.map((kind) => (
            <div key={kind} className="mt-3">
              <ToggleRow
                label={STRENGTH_OPTIONS.find((o) => o.id === kind)?.label ?? kind}
                on={Boolean(log.strength?.[kind] ?? (kind === "gym" ? log.gym : false))}
                onToggle={() =>
                  patch(dateKey, {
                    strength: {
                      ...(log.strength ?? {}),
                      [kind]: !(log.strength?.[kind] ?? (kind === "gym" ? log.gym : false)),
                    },
                  })
                }
              />
            </div>
          ))}
        </Section>
      )}

      {plan.sleep.enabled && (
        <Section icon={Moon} title="Sono">
          {plan.sleep.mode === "cpap" ? (
            <>
              <MinutesRow
                label="Horas de CPAP"
                value={log.cpapHours ?? 0}
                step={0.5}
                suffix="h"
                onChange={(n) => patch(dateKey, { cpapHours: n })}
              />
              <div className="mt-3">
                <ToggleRow
                  label="Usei durante todo o sono"
                  on={Boolean(log.cpapFullNight)}
                  onToggle={() => patch(dateKey, { cpapFullNight: !log.cpapFullNight })}
                />
              </div>
            </>
          ) : (
            <>
              <MinutesRow
                label="Horas de sono"
                value={log.sleepHours ?? 0}
                step={0.5}
                suffix="h"
                onChange={(n) => patch(dateKey, { sleepHours: n })}
              />
              <div className="mt-3">
                <ToggleRow
                  label="Me senti satisfeito com o sono"
                  on={Boolean(log.sleepSatisfied)}
                  onToggle={() => patch(dateKey, { sleepSatisfied: !log.sleepSatisfied })}
                />
              </div>
            </>
          )}
        </Section>
      )}

      {plan.spirituality.enabled && (
        <Section icon={Sparkles} title="Espiritualidade">
          <ToggleRow
            label="Oração diária"
            on={Boolean(log.prayer)}
            onToggle={() => patch(dateKey, { prayer: !log.prayer })}
          />
          <div className="mt-2">
            <ToggleRow
              label="Contato com a natureza"
              on={Boolean(log.nature)}
              onToggle={() => patch(dateKey, { nature: !log.nature })}
            />
          </div>
          <div className="mt-2">
            <ToggleRow
              label="Tempo de contemplação"
              on={Boolean(log.contemplation)}
              onToggle={() => patch(dateKey, { contemplation: !log.contemplation })}
            />
          </div>
          <div className="mt-2">
            <ToggleRow
              label="Oração ou meditação"
              on={Boolean(log.meditation)}
              onToggle={() => patch(dateKey, { meditation: !log.meditation })}
            />
          </div>
        </Section>
      )}

      {plan.food.enabled && (
        <Section icon={Salad} title="Alimentação">
          <div className="grid grid-cols-1 gap-2">
            <MealChoice
              label="Segui a rotina da nutricionista"
              hint="✓"
              active={log.meals === "ok"}
              onClick={() => patch(dateKey, { meals: toggleMeal(log.meals, "ok") })}
            />
            <MealChoice
              label="Jejum prolongado"
              hint="J"
              active={log.meals === "fast"}
              onClick={() => patch(dateKey, { meals: toggleMeal(log.meals, "fast") })}
            />
            <MealChoice
              label="Improvisação total das refeições"
              hint="I"
              active={log.meals === "improv"}
              onClick={() => patch(dateKey, { meals: toggleMeal(log.meals, "improv") })}
            />
          </div>
        </Section>
      )}

      {plan.social.enabled && (
        <Section icon={Users} title="Conexões sociais">
          <p className="mb-3 text-xs text-muted-foreground">Como foi a rede de apoio nesta semana.</p>
          <div className="grid gap-2">
            {(
              [
                ["support", "Tive rede de apoio"],
                ["present", "Me senti presente"],
                ["lonely", "Me senti sozinho"],
              ] as [SocialStatus, string][]
            ).map(([id, label]) => (
              <MealChoice
                key={id}
                label={label}
                hint=""
                active={log.social === id}
                onClick={() => patch(dateKey, { social: log.social === id ? undefined : id })}
              />
            ))}
          </div>
        </Section>
      )}
    </div>
  );
}

function minutesFor(log: DayLog, kind: AerobicKind): number {
  if (log.aerobic?.[kind] != null) return log.aerobic[kind] ?? 0;
  if (kind === "walk") return log.walkMinutes ?? 0;
  return 0;
}

function toggleMeal(current: MealsStatus | undefined, next: MealsStatus): MealsStatus | undefined {
  return current === next ? undefined : next;
}

function Section({
  icon: Icon,
  title,
  children,
}: {
  icon: LucideIcon;
  title: string;
  children: ReactNode;
}) {
  return (
    <section className="rounded-xl bg-card p-4 shadow-[var(--shadow-border)]">
      <h3 className="mb-3 flex items-center gap-2 font-display text-base font-semibold">
        <Icon className="size-4 text-primary" />
        {title}
      </h3>
      {children}
    </section>
  );
}

function ToggleRow({ label, on, onToggle }: { label: string; on: boolean; onToggle: () => void }) {
  return (
    <button
      type="button"
      onClick={onToggle}
      className="flex w-full items-center justify-between rounded-md bg-secondary/70 px-3 py-3 text-left"
    >
      <span className="text-sm font-medium">{label}</span>
      <span className={cn("flex h-6 w-11 items-center rounded-full p-0.5 transition-colors", on ? "bg-primary" : "bg-border")}>
        <span className={cn("size-5 rounded-full bg-card shadow-sm transition-transform", on && "translate-x-5")} />
      </span>
    </button>
  );
}

function MinutesRow({
  label,
  value,
  onChange,
  step = 10,
  suffix = "min",
}: {
  label: string;
  value: number;
  onChange: (n: number) => void;
  step?: number;
  suffix?: string;
}) {
  return (
    <div className="mt-3">
      <p className="mb-2 text-sm font-medium">{label}</p>
      <div className="flex items-center gap-2">
        <Button type="button" variant="outline" onClick={() => onChange(Math.max(0, Math.round((value - step) * 10) / 10))}>
          −
        </Button>
        <Input
          type="number"
          min={0}
          step={step}
          inputMode="decimal"
          className="text-center text-lg tabular-nums"
          value={value}
          onChange={(e) => onChange(Math.max(0, Number(e.target.value) || 0))}
        />
        <span className="text-sm text-muted-foreground">{suffix}</span>
        <Button type="button" variant="outline" onClick={() => onChange(Math.round((value + step) * 10) / 10)}>
          +
        </Button>
      </div>
    </div>
  );
}

function MealChoice({
  label,
  hint,
  active,
  onClick,
}: {
  label: string;
  hint: string;
  active: boolean;
  onClick: () => void;
}) {
  return (
    <button
      type="button"
      onClick={onClick}
      className={cn(
        "flex min-h-12 items-center justify-between rounded-md px-3 py-3 text-left text-sm",
        active ? "bg-primary text-primary-foreground" : "bg-secondary",
      )}
    >
      <span>{label}</span>
      {hint ? <span className="text-xs font-semibold">{hint}</span> : null}
    </button>
  );
}

function toggleSymptom(log: DayLog, code: SymptomCode): SymptomEntry[] {
  const current = log.symptoms ?? [];
  if (current.some((s) => s.code === code)) return current.filter((s) => s.code !== code);
  if (code === "S") return [{ code: "S", intensity: 0 }];
  return [...current.filter((s) => s.code !== "S"), { code, intensity: 1 }];
}

function setIntensity(log: DayLog, code: SymptomCode, intensity: number): SymptomEntry[] {
  const current = log.symptoms ?? [];
  const found = current.find((s) => s.code === code);
  if (!found) return [...current.filter((s) => s.code !== "S"), { code, intensity }];
  return current.map((s) => (s.code === code ? { ...s, intensity } : s));
}

