                  {module.responseCount} {module.responseCount === 1 ? "registro" : "registros"}
                  {module.lastResponseOn
                    ? " · último " + module.lastResponseOn.split("-").reverse().join("/")
                    : ""}
                </span>
              </summary>

              {module.highlights.length > 0 ? (
                <dl className="mt-3 divide-y divide-border/60">
                  {module.highlights.map((highlight) => (
                    <div
                      key={highlight.label}
                      className="grid gap-1 py-2 text-sm sm:grid-cols-[minmax(0,1fr)_minmax(0,1.2fr)] sm:gap-4"
                    >
                      <dt className="text-muted-foreground">{highlight.label}</dt>
                      <dd className="font-medium sm:text-right">{highlight.value}</dd>
                    </div>
                  ))}
                </dl>
              ) : (
                <p className="mt-3 text-xs text-muted-foreground">
                  Registros sem campos resumíveis adicionais.
                </p>
              )}
            </details>
          ))
        )}
      </div>
    </section>
  );
}

function Metric({ label, value }: { label: string; value: string }) {
  return (
    <div className="rounded-lg bg-secondary/50 p-3">
      <p className="text-[11px] text-muted-foreground">{label}</p>
      <p className="mt-1 font-display text-xl font-semibold tabular-nums">{value}</p>
    </div>
  );
}

import { cn } from "@/lib/utils";

type Props = {
  value: number;
  max: number;
  label: string;
  detail: string;
  className?: string;
};

export function HabitRing({ value, max, label, detail, className }: Props) {
  const pct = max <= 0 ? 0 : Math.min(1, value / max);
  const r = 18;
  const c = 2 * Math.PI * r;
  const dash = c * pct;

  return (
    <div className={cn("flex items-center gap-3", className)}>
      <svg viewBox="0 0 44 44" className="size-12 shrink-0 -rotate-90">
        <circle
          cx="22"
          cy="22"
          r={r}
          fill="none"
          className="stroke-secondary"
          strokeWidth="5"
        />
        <circle
          cx="22"
          cy="22"
          r={r}
          fill="none"
          className="stroke-primary"
          strokeWidth="5"
          strokeLinecap="round"
          strokeDasharray={`${dash} ${c - dash}`}
        />
      </svg>
      <div className="min-w-0">
        <p className="text-sm font-medium leading-tight">{label}</p>
        <p className="text-xs text-muted-foreground tabular-nums">{detail}</p>
      </div>
    </div>
  );
}

