export function JourneyEngineEditor() {
  const plan = useJournal((s) => s.journeyPlan);
  const meta = useJournal((s) => s.journeyMeta);
  const setPlan = useJournal((s) => s.setJourneyPlan);
  const saveDraft = useJournal((s) => s.saveJourneyDraft);
  const publish = useJournal((s) => s.publishJourney);
  const [busy, setBusy] = useState<"save" | "publish" | null>(null);
  const [message, setMessage] = useState<string | null>(null);

  const statusLabel = useMemo(() => {
    if (meta.status === "published") return `Publicada · versão ${meta.currentVersion}`;
    if (meta.status === "in_review") return `Em revisão · publicada v${meta.currentVersion}`;
    if (meta.status === "completed") return "Concluída";
    if (meta.status === "archived") return "Arquivada";
    return "Rascunho";
  }, [meta]);

  function updateModule(id: string, patch: Partial<JourneyModule>) {
    setPlan({
      modules: plan.modules.map((module) =>
        module.id === id ? { ...module, ...patch } : module,
      ),
    });
  }

  function addModule(type: JourneyModuleType) {
    setPlan({
      modules: [
        ...plan.modules,
        {
          id: crypto.randomUUID(),
          type,
          title: JOURNEY_MODULE_LABELS[type],
          enabled: true,
          instructions: "",
          frequency: { kind: type === "eating_behavior" ? "event_based" : "daily" },
          startDate: "",
          endDate: "",
          reviewDate: "",
          required: false,
          questions: [],
        },
      ],
    });
  }

  async function persist(kind: "save" | "publish") {
    setBusy(kind);
    setMessage(null);
    try {
      if (kind === "save") {
        await saveDraft();
        setMessage("Rascunho salvo.");
      } else {
        await saveDraft();
        await publish();
        setMessage("Jornada publicada para o paciente.");
      }
    } catch (error) {
      setMessage(error instanceof Error ? error.message : "Não foi possível salvar.");
    } finally {
      setBusy(null);
    }
  }

  return (
    <div className="space-y-5">
      <section className="rounded-xl border border-primary/20 bg-accent/40 p-5">
        <div className="flex flex-wrap items-start justify-between gap-3">
          <div>
            <p className="text-[11px] font-semibold uppercase tracking-[0.16em] text-primary">
              Motor da Jornada V2
            </p>
            <h2 className="mt-1 font-display text-xl font-semibold">Plano individual</h2>
            <p className="mt-1 text-sm text-muted-foreground">{statusLabel}</p>
          </div>
          <div className="flex gap-2">
            <Button
              type="button"
              variant="outline"
              disabled={Boolean(busy)}
              onClick={() => void persist("save")}
            >
              {busy === "save" ? "Salvando…" : "Salvar rascunho"}
            </Button>
            <Button
              type="button"
              disabled={Boolean(busy)}
              onClick={() => void persist("publish")}
            >
              <Send className="size-4" />
              {busy === "publish" ? "Publicando…" : "Publicar"}
            </Button>
          </div>
        </div>
        {message && <p className="mt-3 text-sm text-muted-foreground">{message}</p>}
      </section>

      <section className="space-y-3 rounded-xl bg-card p-5 shadow-[var(--shadow-border)]">
        <div>
          <h3 className="font-display text-lg font-semibold">Começar por um modelo</h3>
          <p className="mt-1 text-xs text-muted-foreground">
            O modelo apenas preenche um rascunho. Tudo pode ser alterado antes da publicação.
          </p>
        </div>
        <div className="flex flex-wrap gap-2">
          <Button
            type="button"
            variant="outline"
            onClick={() => setPlan(agirInitialTemplate())}
          >
            Método AGIR — ciclo inicial
          </Button>
          <Button
            type="button"
            variant="outline"
            onClick={() => setPlan(sweetsThirtyDayTemplate())}
          >
            Doces/comer emocional — 30 dias
          </Button>
        </div>
      </section>

      <section className="space-y-4 rounded-xl bg-card p-5 shadow-[var(--shadow-border)]">
        <h3 className="font-display text-lg font-semibold">Identificação do ciclo</h3>
        <Field label="Nome da Jornada">
          <Input
            value={plan.title}
            onChange={(e) => setPlan({ title: e.target.value })}
            placeholder="Ex.: Ciclo inicial — saúde metabólica"
          />
        </Field>
        <div className="grid gap-3 sm:grid-cols-3">
          <Field label="Data de início">
            <Input
              type="date"
              value={plan.startDate}
              onChange={(e) => setPlan({ startDate: e.target.value })}
            />
          </Field>
          <Field label="Duração (dias)">
            <Input
              type="number"
              min={1}
              max={3650}
              value={plan.durationDays ?? ""}
              onChange={(e) =>
                setPlan({
                  durationDays: e.target.value ? Number(e.target.value) : null,
                })
              }
            />
          </Field>
          <Field label="Data de revisão">
            <Input
              type="date"
              value={plan.reviewDate}
              onChange={(e) => setPlan({ reviewDate: e.target.value })}
            />
          </Field>
        </div>
        <Field label="O que trouxe o paciente até aqui?">
          <Textarea
            value={plan.motivation}
            onChange={(e) => setPlan({ motivation: e.target.value })}
          />
        </Field>
        <Field label="O que é importante para o paciente neste momento?">
          <Textarea
            value={plan.patientValues}
            onChange={(e) => setPlan({ patientValues: e.target.value })}
          />
        </Field>
        <Field label="Objetivo geral desta Jornada">
          <Textarea
            value={plan.objective}
            onChange={(e) => setPlan({ objective: e.target.value })}
          />
        </Field>
      </section>

      <section className="space-y-3">
        <div className="flex items-center justify-between gap-3">
          <div>
            <h3 className="font-display text-lg font-semibold">Prioridades atuais</h3>
            <p className="text-xs text-muted-foreground">Até três por ciclo.</p>
          </div>
          <Button
            type="button"
            variant="outline"
            size="sm"
            disabled={plan.priorities.length >= 3}
            onClick={() =>
              setPlan({
                priorities: [
                  ...plan.priorities,
                  {
                    id: crypto.randomUUID(),
                    title: "",
                    description: "",
                    tracking: "",
                    reviewDate: "",
                  },
                ],
              })
            }
          >
            <Plus className="size-4" />
            Prioridade
          </Button>
        </div>
        {plan.priorities.map((priority, index) => (
          <div key={priority.id} className="space-y-3 rounded-xl bg-card p-4 shadow-[var(--shadow-border)]">
            <div className="flex justify-between gap-3">
              <p className="font-medium">Prioridade {index + 1}</p>
              <button
                type="button"
                className="text-xs text-destructive"
                onClick={() =>
                  setPlan({
                    priorities: plan.priorities.filter((item) => item.id !== priority.id),
                  })
                }
              >
                Remover
              </button>
            </div>
            <Input
              value={priority.title}
              placeholder="Título"
              onChange={(e) =>
                setPlan({
                  priorities: plan.priorities.map((item) =>
                    item.id === priority.id ? { ...item, title: e.target.value } : item,
                  ),
                })
              }
            />
            <Textarea
              value={priority.description}
              placeholder="Descrição"
              onChange={(e) =>
                setPlan({
                  priorities: plan.priorities.map((item) =>
                    item.id === priority.id ? { ...item, description: e.target.value } : item,
                  ),
                })
              }
            />
            <Input
              value={priority.tracking}
              placeholder="Como vamos acompanhar"
              onChange={(e) =>
                setPlan({
                  priorities: plan.priorities.map((item) =>
                    item.id === priority.id ? { ...item, tracking: e.target.value } : item,
                  ),
                })
              }
            />
          </div>
        ))}
      </section>

      <section className="space-y-3">
        <div>
          <h3 className="font-display text-lg font-semibold">Módulos do acompanhamento</h3>
          <p className="text-xs text-muted-foreground">
            O paciente verá somente os módulos publicados na Jornada.
          </p>
        </div>

        <div className="flex flex-wrap gap-2">
          {MODULE_TYPES.map(([type, label]) => (
            <Button
              key={type}
              type="button"
              variant="outline"
              size="sm"
              onClick={() => addModule(type)}
            >
              <Plus className="size-3.5" />
              {label}
            </Button>
          ))}
        </div>

        {plan.modules.length === 0 && (
          <div className="rounded-xl border border-dashed p-6 text-center text-sm text-muted-foreground">
            Nenhum módulo configurado. A Jornada permanece sem registros obrigatórios.
          </div>
        )}

        {plan.modules.map((module) => (
          <ModuleEditor
            key={module.id}
            module={module}
            onChange={(patch) => updateModule(module.id, patch)}
            onRemove={() =>
              setPlan({ modules: plan.modules.filter((item) => item.id !== module.id) })
            }
          />
        ))}
      </section>

      <JourneyCareActionsEditor />
    </div>
  );
}

function ModuleEditor({
  module,
  onChange,
  onRemove,
}: {
  module: JourneyModule;
  onChange: (patch: Partial<JourneyModule>) => void;
  onRemove: () => void;
}) {
  const addQuestion = () => {
    const question: JourneyQuestion = {
      id: crypto.randomUUID(),
      label: "",
      type: "short_text",
      required: false,
    };
    onChange({ questions: [...module.questions, question] });
  };

  return (
    <div className="space-y-4 rounded-xl bg-card p-5 shadow-[var(--shadow-border)]">
      <div className="flex items-start justify-between gap-3">
        <div className="min-w-0 flex-1">
          <p className="text-[11px] font-semibold uppercase tracking-[0.14em] text-primary">
            {JOURNEY_MODULE_LABELS[module.type]}
          </p>
          <Input
            className="mt-2"
            value={module.title}
            onChange={(e) => onChange({ title: e.target.value })}
          />
        </div>
        <button type="button" className="text-xs text-destructive" onClick={onRemove}>
          Remover
        </button>
      </div>

      <Field label="Orientação visível ao paciente">
        <Textarea
          value={module.instructions}
          onChange={(e) => onChange({ instructions: e.target.value })}
        />
      </Field>

      <div className="grid gap-3 sm:grid-cols-2">
        <Field label="Frequência">
          <select
            className="h-10 w-full rounded-md border border-input bg-background px-3 text-sm"
            value={module.frequency.kind}
            onChange={(e) =>
              onChange({
                frequency: {
                  ...module.frequency,
                  kind: e.target.value as JourneyFrequencyKind,
                },
              })
            }
          >
            {Object.entries(JOURNEY_FREQUENCY_LABELS).map(([id, label]) => (
              <option key={id} value={id}>
                {label}
              </option>
            ))}
          </select>
        </Field>
        <Field label="Data de revisão">
          <Input
            type="date"
            value={module.reviewDate}
            onChange={(e) => onChange({ reviewDate: e.target.value })}
          />
        </Field>
      </div>

      {module.frequency.kind === "selected_days" && (
        <div>
          <p className="mb-2 text-xs font-medium text-muted-foreground">Dias da semana</p>
          <div className="flex flex-wrap gap-2">
            {["Dom", "Seg", "Ter", "Qua", "Qui", "Sex", "Sáb"].map((label, day) => {
              const selected = module.frequency.daysOfWeek?.includes(day) ?? false;
              return (
                <button
                  key={label}
                  type="button"
                  className={
                    selected
                      ? "rounded-md bg-primary px-3 py-2 text-xs text-primary-foreground"
                      : "rounded-md bg-secondary px-3 py-2 text-xs"
                  }
                  onClick={() => {
                    const days = module.frequency.daysOfWeek ?? [];
                    onChange({
                      frequency: {
                        ...module.frequency,
                        daysOfWeek: selected
                          ? days.filter((item) => item !== day)
                          : [...days, day].sort(),
                      },
                    });
                  }}
                >
                  {label}
                </button>
              );
            })}
          </div>
        </div>
      )}

      <div className="flex items-center justify-between gap-3">
        <div>
          <p className="text-sm font-medium">Perguntas</p>
          <p className="text-xs text-muted-foreground">
            Defina apenas o que precisa ser acompanhado neste ciclo.
          </p>
        </div>
        <Button type="button" variant="outline" size="sm" onClick={addQuestion}>
          <Plus className="size-4" />
          Pergunta
        </Button>
      </div>

      {module.questions.map((question) => (
        <QuestionEditor
          key={question.id}
          question={question}
          questions={module.questions}
          onChange={(patch) =>
            onChange({
              questions: module.questions.map((item) =>
                item.id === question.id ? { ...item, ...patch } : item,
              ),
            })
          }
          onRemove={() =>
            onChange({
              questions: module.questions.filter((item) => item.id !== question.id),
              alerts: (module.alerts ?? []).filter(
                (rule) => rule.questionId !== question.id,
              ),
            })
          }
        />
      ))}

      <div className="border-t border-border/60 pt-4">
        <div className="flex items-start justify-between gap-3">
          <div>
            <p className="text-sm font-medium">Alertas para a médica</p>
            <p className="mt-1 text-xs text-muted-foreground">
              Opcional. Só gera alerta quando uma regra publicada for atendida.
            </p>
          </div>
          <Button
            type="button"
            variant="outline"
            size="sm"
            disabled={module.questions.length === 0}
            onClick={() => {
              const first = module.questions[0];
              if (!first) return;
              const rule: JourneyAlertRule = {
                id: crypto.randomUUID(),
                questionId: first.id,
                operator: "equals",
                value: defaultRuleValue(first),
                title: "",
                severity: "attention",
              };
              onChange({ alerts: [...(module.alerts ?? []), rule] });
            }}
          >
            <Plus className="size-4" />
            Alerta
          </Button>
        </div>

        {(module.alerts ?? []).length === 0 ? (
          <p className="mt-3 text-xs text-muted-foreground">
            Nenhum alerta configurado neste módulo.
          </p>
        ) : (
          <div className="mt-3 space-y-3">
            {(module.alerts ?? []).map((rule) => (
              <AlertRuleEditor
                key={rule.id}
                rule={rule}
                questions={module.questions}
                onChange={(patch) =>
                  onChange({
                    alerts: (module.alerts ?? []).map((item) =>
                      item.id === rule.id ? { ...item, ...patch } : item,
                    ),
                  })
                }
                onRemove={() =>
                  onChange({
                    alerts: (module.alerts ?? []).filter(
                      (item) => item.id !== rule.id,
                    ),
                  })
                }
              />
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

function AlertRuleEditor({
  rule,
  questions,
  onChange,
  onRemove,
}: {
  rule: JourneyAlertRule;
  questions: JourneyQuestion[];
  onChange: (patch: Partial<JourneyAlertRule>) => void;
  onRemove: () => void;
}) {
  const question = questions.find((item) => item.id === rule.questionId);
  if (!question) return null;

  const numeric =
    question.type === "scale" ||
    question.type === "number" ||
    question.type === "duration";

  return (
    <div className="space-y-3 rounded-lg bg-secondary/40 p-3">
      <div className="flex items-start justify-between gap-3">
        <p className="text-xs font-semibold uppercase tracking-[0.12em] text-primary">
          Regra de alerta
        </p>
        <button type="button" className="text-xs text-destructive" onClick={onRemove}>
          Remover
        </button>
      </div>

      <Field label="Pergunta observada">
        <select
          className="h-10 w-full rounded-md border border-input bg-background px-3 text-sm"
          value={rule.questionId}
          onChange={(e) => {
            const nextQuestion = questions.find((item) => item.id === e.target.value);
            onChange({
              questionId: e.target.value,
              operator: "equals",
              value: nextQuestion ? defaultRuleValue(nextQuestion) : "",
            });
          }}
        >
          {questions.map((item) => (
            <option key={item.id} value={item.id}>
              {item.label || "Pergunta sem título"}
            </option>
          ))}
        </select>
      </Field>

      <div className="grid gap-2 sm:grid-cols-2">
        <Field label="Condição">
          <select
            className="h-10 w-full rounded-md border border-input bg-background px-3 text-sm"
            value={rule.operator}
            onChange={(e) =>
              onChange({
                operator: e.target.value as JourneyAlertRule["operator"],
              })
            }
          >
            <option value="equals">é igual a</option>
            <option value="not_equals">é diferente de</option>
            {(question.type === "multiple_choice" ||
              question.type === "short_text" ||
              question.type === "long_text") && (
              <option value="includes">contém</option>
            )}
            {numeric && <option value="gte">é maior ou igual a</option>}
            {numeric && <option value="lte">é menor ou igual a</option>}
          </select>
        </Field>
        <Field label="Valor">
          <ConditionValueEditor
            control={question}
            value={rule.value}
            onChange={(value) => onChange({ value })}
          />
        </Field>
      </div>

      <Field label="Mensagem do alerta">
        <Input
          value={rule.title}
          placeholder="Ex.: Revisar resposta deste módulo"
          onChange={(e) => onChange({ title: e.target.value })}
        />
      </Field>

      <Field label="Prioridade visual">
        <select
          className="h-10 w-full rounded-md border border-input bg-background px-3 text-sm"
          value={rule.severity}
          onChange={(e) =>
            onChange({
              severity: e.target.value as JourneyAlertRule["severity"],
            })
          }
        >
          <option value="attention">Atenção</option>
          <option value="important">Importante</option>
        </select>
      </Field>
    </div>
  );
}

function defaultRuleValue(question: JourneyQuestion): string | number | boolean {
  if (question.type === "boolean" || question.type === "event") return true;
  if (
    question.type === "scale" ||
    question.type === "number" ||
    question.type === "duration"
  ) {
    return question.min ?? 0;
  }
  if (
    question.type === "single_choice" ||
    question.type === "multiple_choice" ||
    question.type === "emotion"
  ) {
    return question.options?.[0]?.id ?? "";
  }
  return "";
}

function QuestionEditor({
  question,
  questions,
  onChange,
  onRemove,
}: {
  question: JourneyQuestion;
  questions: JourneyQuestion[];
  onChange: (patch: Partial<JourneyQuestion>) => void;
  onRemove: () => void;
}) {
  const controlQuestion = questions.find(
    (item) => item.id === question.condition?.questionId,
  );
  const currentIndex = questions.findIndex((item) => item.id === question.id);
  const possibleControls = currentIndex > 0 ? questions.slice(0, currentIndex) : [];
  return (
    <div className="grid gap-3 rounded-lg bg-secondary/40 p-3 sm:grid-cols-[1fr_180px_auto]">
      <Input
        value={question.label}
        placeholder="Pergunta para o paciente"
        onChange={(e) => onChange({ label: e.target.value })}
      />
      <select
        className="h-10 rounded-md border border-input bg-background px-3 text-sm"
        value={question.type}
        onChange={(e) => onChange({ type: e.target.value as JourneyQuestionType })}
      >
        {QUESTION_TYPES.map((type) => (
          <option key={type.id} value={type.id}>
            {type.label}
          </option>
        ))}
      </select>
      <Button type="button" variant="ghost" onClick={onRemove}>
        Remover
      </Button>
      <div className="flex items-center gap-2 sm:col-span-3">
        <button
          type="button"
          className={
            question.required
              ? "rounded-md bg-primary px-3 py-2 text-xs text-primary-foreground"
              : "rounded-md bg-secondary px-3 py-2 text-xs"
          }
          onClick={() => onChange({ required: !question.required })}
        >
          {question.required ? "Obrigatória" : "Opcional"}
        </button>
      </div>

      {(question.type === "scale" ||
        question.type === "number" ||
        question.type === "duration") && (
        <div className="grid gap-2 sm:col-span-3 sm:grid-cols-3">
          <Field label="Mínimo">
            <Input
              type="number"
              value={question.min ?? ""}
              onChange={(e) =>
                onChange({ min: e.target.value === "" ? undefined : Number(e.target.value) })
              }
            />
          </Field>
          <Field label="Máximo">
            <Input
              type="number"
              value={question.max ?? ""}
              onChange={(e) =>
                onChange({ max: e.target.value === "" ? undefined : Number(e.target.value) })
              }
            />
          </Field>
          <Field label="Passo">
            <Input
              type="number"
              value={question.step ?? ""}
              onChange={(e) =>
                onChange({ step: e.target.value === "" ? undefined : Number(e.target.value) })
              }
            />
          </Field>
        </div>
      )}

      {(question.type === "single_choice" ||
        question.type === "multiple_choice" ||
        question.type === "emotion") && (
        <div className="sm:col-span-3">
          <Label className="text-xs">Opções, separadas por ponto e vírgula</Label>
          <Input
            className="mt-1"
            value={(question.options ?? []).map((option) => option.label).join("; ")}
            onChange={(e) =>
              onChange({
                options: e.target.value
                  .split(";")
                  .map((label) => label.trim())
                  .filter(Boolean)
                  .map((label, index) => ({
                    id: `option-${index + 1}`,
                    label,
                  })),
              })
            }
          />
        </div>
      )}

      {possibleControls.length > 0 && (
        <div className="space-y-2 border-t border-border/60 pt-3 sm:col-span-3">
          <Label className="text-xs">Regra de exibição</Label>
          <select
            className="h-10 w-full rounded-md border border-input bg-background px-3 text-sm"
            value={question.condition?.questionId ?? ""}
            onChange={(e) =>
              onChange({
                condition: e.target.value
                  ? {
                      questionId: e.target.value,
                      operator: "equals",
                      value: "",
                    }
                  : undefined,
              })
            }
          >
            <option value="">Sempre mostrar</option>
            {possibleControls.map((item) => (
              <option key={item.id} value={item.id}>
                Mostrar dependendo de: {item.label || "Pergunta sem título"}
              </option>
            ))}
          </select>

          {question.condition && controlQuestion && (
            <div className="grid gap-2 sm:grid-cols-2">
              <select
                className="h-10 rounded-md border border-input bg-background px-3 text-sm"
                value={question.condition.operator}
                onChange={(e) =>
                  onChange({
                    condition: {
                      ...question.condition!,
                      operator: e.target.value as "equals" | "not_equals" | "includes",
                    },
                  })
                }
              >
                <option value="equals">é igual a</option>
                <option value="not_equals">é diferente de</option>
                <option value="includes">contém</option>
              </select>
              <ConditionValueEditor
                control={controlQuestion}
                value={question.condition.value}
                onChange={(value) =>
                  onChange({
                    condition: {
                      ...question.condition!,
                      value,
                    },
                  })
                }
              />
            </div>
          )}
        </div>
      )}
    </div>
  );
}

function ConditionValueEditor({
  control,
  value,
  onChange,
}: {
  control: JourneyQuestion;
  value: string | number | boolean;
  onChange: (value: string | number | boolean) => void;
}) {
  if (control.type === "boolean" || control.type === "event") {
    return (
      <select
        className="h-10 rounded-md border border-input bg-background px-3 text-sm"
        value={String(value)}
        onChange={(e) => onChange(e.target.value === "true")}
      >
        <option value="">Escolha</option>
        <option value="true">Sim</option>
        <option value="false">Não</option>
      </select>
    );
  }

  if (
    control.type === "single_choice" ||
    control.type === "emotion" ||
    control.type === "multiple_choice"
  ) {
    return (
      <select
        className="h-10 rounded-md border border-input bg-background px-3 text-sm"
        value={String(value)}
        onChange={(e) => onChange(e.target.value)}
      >
        <option value="">Escolha uma opção</option>
        {(control.options ?? []).map((option) => (
          <option key={option.id} value={option.id}>
            {option.label}
          </option>
        ))}
      </select>
    );
  }

  if (
    control.type === "scale" ||
    control.type === "number" ||
    control.type === "duration"
  ) {
    return (
      <Input
        type="number"
        value={typeof value === "number" ? value : ""}
        onChange={(e) => onChange(Number(e.target.value))}
      />
    );
  }

  return (
    <Input value={String(value ?? "")} onChange={(e) => onChange(e.target.value)} />
  );
}

function Field({ label, children }: { label: string; children: ReactNode }) {
  return (
    <div className="space-y-1.5">
      <Label>{label}</Label>
      {children}
    </div>
  );
}

import { format, parseISO, subDays } from "date-fns";
import { ptBR } from "date-fns/locale";
import { useMemo, useState } from "react";
import { responseEntries } from "@/lib/journey-response-format";
import { useJournal } from "@/lib/journal-store";
import type {
  JourneyModule,
  JourneyModuleResponse,
  JourneyQuestion,
} from "@/lib/types";

type Period = "7" | "30" | "90" | "all";

export function JourneyEvolution() {
  const plan = useJournal((s) => s.journeyPlan);
  const responses = useJournal((s) => s.journeyResponses);
  const [period, setPeriod] = useState<Period>("30");
  const [moduleId, setModuleId] = useState("all");

  const activeModules = plan.modules.filter((module) => module.enabled);
  const filteredResponses = useMemo(
    () => filterResponses(responses, period),
    [responses, period],
  );
  const visibleModules =
    moduleId === "all"
      ? activeModules
      : activeModules.filter((module) => module.id === moduleId);

  return (
    <div className="space-y-5">
      <header>
        <p className="text-xs font-medium uppercase tracking-[0.16em] text-primary">
          {plan.title || "Minha Jornada"}
        </p>
        <h1 className="mt-1 font-display text-3xl font-semibold tracking-tight">
          Evolução
        </h1>
        <p className="mt-2 text-sm leading-relaxed text-muted-foreground">
          Veja seus registros ao longo do tempo. Estes dados ajudam a observar padrões;
          não são uma nota de desempenho.
        </p>
      </header>

      <section className="space-y-3 rounded-xl bg-card p-4 shadow-[var(--shadow-border)]">
        <div>
          <p className="text-xs font-medium text-muted-foreground">Período</p>
          <div className="mt-2 flex flex-wrap gap-2">
            {(
              [
                ["7", "7 dias"],
                ["30", "30 dias"],
                ["90", "3 meses"],
                ["all", "Todo o ciclo"],
              ] as const
            ).map(([id, label]) => (
              <button
                key={id}
                type="button"
                onClick={() => setPeriod(id)}
                className={
                  period === id
                    ? "rounded-md bg-primary px-3 py-2 text-xs font-medium text-primary-foreground"
                    : "rounded-md bg-secondary px-3 py-2 text-xs font-medium"
                }
              >
                {label}
              </button>
            ))}
          </div>
        </div>

        <div>
          <label className="text-xs font-medium text-muted-foreground" htmlFor="module-filter">
            Módulo
          </label>
          <select
            id="module-filter"
            className="mt-2 h-10 w-full rounded-md border border-input bg-background px-3 text-sm"
            value={moduleId}
            onChange={(event) => setModuleId(event.target.value)}
          >
            <option value="all">Todos os módulos</option>
            {activeModules.map((module) => (
              <option key={module.id} value={module.id}>
                {module.title}
              </option>
            ))}
          </select>
        </div>
      </section>

      {visibleModules.map((module) => (
        <ModuleEvolution
          key={module.id}
          module={module}
          responses={filteredResponses.filter(
            (response) => response.moduleId === module.id,
          )}
        />
      ))}

      {visibleModules.length === 0 && (
        <section className="rounded-xl bg-card p-5 text-center shadow-[var(--shadow-border)]">
          <p className="font-medium">Nenhum módulo ativo neste ciclo.</p>
        </section>
      )}
    </div>
  );
}

function ModuleEvolution({
  module,
  responses,
}: {
  module: JourneyModule;
  responses: JourneyModuleResponse[];
}) {
  const sorted = [...responses].sort((a, b) =>
    b.occurredOn.localeCompare(a.occurredOn),
  );
  const last = sorted[0];

  return (
    <section className="space-y-4 rounded-xl bg-card p-5 shadow-[var(--shadow-border)]">
      <div className="flex flex-wrap items-start justify-between gap-3">
        <div>
          <h2 className="font-display text-lg font-semibold">{module.title}</h2>
          <p className="mt-1 text-xs text-muted-foreground">
            {responses.length} {responses.length === 1 ? "registro" : "registros"}
          </p>
        </div>
        {last && (
          <p className="text-xs text-muted-foreground">
            Último: {format(parseISO(last.occurredOn), "d 'de' MMM", { locale: ptBR })}
          </p>
        )}
      </div>

      {responses.length === 0 ? (
        <p className="text-sm text-muted-foreground">
          Ainda não há registros deste módulo no período selecionado.
        </p>
      ) : (
        <>
          {module.questions.map((question) => (
            <QuestionEvolution
              key={question.id}
              question={question}
              responses={responses}
            />
          ))}

          {module.questions.length === 0 && (
            <RecentDates responses={sorted} />
          )}
        </>
      )}
    </section>
  );
}

function QuestionEvolution({
  question,
  responses,
}: {
  question: JourneyQuestion;
  responses: JourneyModuleResponse[];
}) {
  const values = responses
    .map((response) => ({
      response,
      value: response.answers[question.id],
    }))
    .filter(({ value }) => value !== undefined && value !== null && value !== "");

  if (values.length === 0) return null;

  if (
    question.type === "scale" ||
    question.type === "number" ||
    question.type === "duration"
  ) {
    const numbers = values
      .map(({ value }) => (typeof value === "number" ? value : Number.NaN))
      .filter(Number.isFinite);
    if (numbers.length === 0) return null;
    const average = numbers.reduce((sum, value) => sum + value, 0) / numbers.length;
    const suffix = question.type === "duration" ? " min" : "";
    return (
      <div className="rounded-lg bg-secondary/50 p-3">
        <p className="text-sm font-medium">{question.label}</p>
        <dl className="mt-2 grid grid-cols-3 gap-2 text-center">
          <Metric label="Média" value={`${formatNumber(average)}${suffix}`} />
          <Metric label="Menor" value={`${formatNumber(Math.min(...numbers))}${suffix}`} />
          <Metric label="Maior" value={`${formatNumber(Math.max(...numbers))}${suffix}`} />
        </dl>
      </div>
    );
  }

  if (question.type === "boolean" || question.type === "event") {
    const yes = values.filter(({ value }) => value === true).length;
    const no = values.filter(({ value }) => value === false).length;
    return (
      <Distribution
        title={question.label}
        rows={[
          ["Sim", yes],
          ["Não", no],
        ]}
      />
    );
  }

  if (
    question.type === "single_choice" ||
    question.type === "emotion"
  ) {
    const rows = (question.options ?? []).map(
      (option) =>
        [
          option.label,
          values.filter(({ value }) => value === option.id).length,
        ] as [string, number],
    );
    return <Distribution title={question.label} rows={rows} />;
  }

  if (question.type === "multiple_choice") {
    const rows = (question.options ?? []).map((option) => [
      option.label,
      values.filter(
        ({ value }) => Array.isArray(value) && value.includes(option.id),
      ).length,
    ] as [string, number]);
    return <Distribution title={question.label} rows={rows} />;
  }

  const recent = values
    .sort((a, b) => b.response.occurredOn.localeCompare(a.response.occurredOn))
    .slice(0, 4);

  return (
    <div className="rounded-lg bg-secondary/50 p-3">
      <p className="text-sm font-medium">{question.label}</p>
      <div className="mt-2 space-y-2">
        {recent.map(({ response, value }) => (
          <div key={response.id} className="text-sm">
            <p className="text-xs text-muted-foreground">
              {format(parseISO(response.occurredOn), "d 'de' MMM", { locale: ptBR })}
            </p>
            <p className="mt-0.5 leading-relaxed">
              {Array.isArray(value) ? value.join(", ") : String(value)}
            </p>
          </div>
        ))}
      </div>
    </div>
  );
}

function Distribution({
  title,
  rows,
}: {
  title: string;
  rows: [string, number][];
}) {
  const max = Math.max(1, ...rows.map(([, count]) => count));
  const total = rows.reduce((sum, [, count]) => sum + count, 0);

  return (
    <div className="rounded-lg bg-secondary/50 p-3">
      <p className="text-sm font-medium">{title}</p>
      <div className="mt-3 space-y-2">
        {rows
          .filter(([, count]) => count > 0 || rows.length <= 4)
          .map(([label, count]) => (
            <div key={label}>
              <div className="flex items-baseline justify-between gap-3 text-xs">
                <span>{label}</span>
                <span className="tabular-nums text-muted-foreground">
                  {count}{total ? ` · ${Math.round((count / total) * 100)}%` : ""}
                </span>
              </div>
              <div className="mt-1 h-1.5 overflow-hidden rounded-full bg-background">
                <div
                  className="h-full rounded-full bg-primary"
                  style={{ width: `${(count / max) * 100}%` }}
                />
              </div>
            </div>
          ))}
      </div>
    </div>
  );
}

function RecentDates({ responses }: { responses: JourneyModuleResponse[] }) {
  return (
    <div>
      <p className="text-sm font-medium">Registros recentes</p>
      <div className="mt-2 flex flex-wrap gap-2">
        {responses.slice(0, 8).map((response) => (
          <span
            key={response.id}
            className="rounded-md bg-secondary px-2.5 py-1.5 text-xs"
          >
            {format(parseISO(response.occurredOn), "d MMM", { locale: ptBR })}
          </span>
        ))}
      </div>
    </div>
  );
}

function Metric({ label, value }: { label: string; value: string }) {
  return (
    <div>
      <dt className="text-[11px] text-muted-foreground">{label}</dt>
      <dd className="mt-0.5 text-sm font-medium tabular-nums">{value}</dd>
    </div>
  );
}

function filterResponses(
  responses: JourneyModuleResponse[],
  period: Period,
): JourneyModuleResponse[] {
  if (period === "all") return responses;
  const days = Number(period);
  const cutoff = subDays(new Date(), days - 1);
  cutoff.setHours(0, 0, 0, 0);
  return responses.filter(
    (response) => parseISO(response.occurredOn) >= cutoff,
  );
}

function formatNumber(value: number): string {
  return Number.isInteger(value) ? String(value) : value.toFixed(1).replace(".", ",");
}

import { format, parseISO } from "date-fns";
import { ptBR } from "date-fns/locale";
import { History } from "lucide-react";
import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { useJournal } from "@/lib/journal-store";
import type { JourneyStatus } from "@/lib/types";

export function JourneyHistoryPanel() {
  const history = useJournal((s) => s.journeyHistory);
  const journeyId = useJournal((s) => s.journeyId);
  const meta = useJournal((s) => s.journeyMeta);
  const closeJourney = useJournal((s) => s.closeCurrentJourney);
  const startNext = useJournal((s) => s.startNextJourney);
  const openJourney = useJournal((s) => s.openPatient);
  const [firstConsult, setFirstConsult] = useState("");
  const [busy, setBusy] = useState<"complete" | "archive" | "next" | null>(null);
  const [error, setError] = useState<string | null>(null);

  if (!journeyId) return null;

  const closed = meta.status === "completed" || meta.status === "archived";

  async function close(status: "completed" | "archived") {
    const label = status === "completed" ? "concluir" : "arquivar";
    if (!window.confirm(`Deseja realmente ${label} esta Jornada? O histórico será preservado.`)) {
      return;
    }
    setBusy(status === "completed" ? "complete" : "archive");
    setError(null);
    try {
      await closeJourney(status);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Não foi possível encerrar o ciclo.");
    } finally {
      setBusy(null);
    }
  }

  async function nextCycle() {
    setBusy("next");
    setError(null);
    try {
      await startNext(firstConsult || undefined);
      setFirstConsult("");
    } catch (err) {
      setError(err instanceof Error ? err.message : "Não foi possível iniciar nova Jornada.");
    } finally {
      setBusy(null);
    }
  }

  return (
    <section className="space-y-4 rounded-xl bg-card p-5 shadow-[var(--shadow-border)]">
      <div>
        <h2 className="flex items-center gap-2 font-display text-lg font-semibold">
          <History className="size-4 text-primary" />
          Ciclos de acompanhamento
        </h2>
        <p className="mt-1 text-xs text-muted-foreground">
          Cada Jornada mantém suas próprias versões, registros, ações e alertas.
        </p>
      </div>

      {!closed ? (
        <div className="flex flex-wrap gap-2">
          <Button
            type="button"
            variant="outline"
            disabled={busy !== null}
            onClick={() => void close("completed")}
          >
            {busy === "complete" ? "Concluindo…" : "Concluir Jornada"}
          </Button>
          <Button
            type="button"
            variant="ghost"
            disabled={busy !== null}
            onClick={() => void close("archived")}
          >
            {busy === "archive" ? "Arquivando…" : "Arquivar ciclo"}
          </Button>
        </div>
      ) : (
        <div className="rounded-lg bg-accent/50 p-4">
          <p className="text-sm font-medium">
            Este ciclo está {meta.status === "completed" ? "concluído" : "arquivado"}.
          </p>
          <p className="mt-1 text-xs text-muted-foreground">
            Inicie uma nova Jornada vazia para continuar o acompanhamento sem alterar o histórico.
          </p>
          <div className="mt-3 grid gap-2 sm:grid-cols-[1fr_auto]">
            <Input
              type="date"
              value={firstConsult}
              onChange={(event) => setFirstConsult(event.target.value)}
              aria-label="Primeira consulta do novo ciclo"
            />
            <Button
              type="button"
              disabled={busy !== null}
              onClick={() => void nextCycle()}
            >
              {busy === "next" ? "Criando…" : "Nova Jornada"}
            </Button>
          </div>
        </div>
      )}

      {error && <p className="text-sm text-destructive">{error}</p>}

      <div className="space-y-2">
        {history.map((cycle) => {
          const selected = cycle.id === journeyId;
          return (
            <div
              key={cycle.id}
              className={
                selected
                  ? "rounded-lg border border-primary/40 bg-accent/40 p-3"
                  : "rounded-lg border border-border/60 p-3"
              }
            >
              <div className="flex items-start justify-between gap-3">
                <div>
                  <p className="text-sm font-medium">{cycle.title || "Jornada"}</p>
                  <p className="mt-1 text-xs text-muted-foreground">
                    {statusLabel(cycle.status)}
                    {cycle.currentVersion > 0 ? ` · versão ${cycle.currentVersion}` : ""}
                    {cycle.startDate
                      ? ` · início ${format(parseISO(cycle.startDate), "dd/MM/yyyy", { locale: ptBR })}`
                      : ""}
                  </p>
                </div>
                {selected ? (
                  <span className="text-xs font-medium text-primary">Aberta</span>
                ) : (
                  <button
                    type="button"
                    className="text-xs font-medium text-primary"
                    onClick={() => void openJourney(cycle.id)}
                  >
                    Ver
                  </button>
                )}
              </div>
            </div>
          );
        })}
      </div>
    </section>
  );
}

function statusLabel(status: JourneyStatus): string {
  if (status === "published") return "Em acompanhamento";
  if (status === "in_review") return "Em revisão";
  if (status === "completed") return "Concluída";
  if (status === "archived") return "Arquivada";
  return "Rascunho";
}

import { Check, ChevronDown, ChevronUp } from "lucide-react";
import { type ReactNode, useMemo, useState } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { useJournal } from "@/lib/journal-store";
import type {
  JourneyAnswerValue,
  JourneyModule,
  JourneyQuestion,
} from "@/lib/types";
import { cn } from "@/lib/utils";

export function JourneyModuleForm({
  module,
  occurredOn,
  collapsible = false,
}: {
  module: JourneyModule;
  occurredOn: string;
  collapsible?: boolean;
}) {
  const save = useJournal((s) => s.saveModuleResponse);
  const [answers, setAnswers] = useState<Record<string, JourneyAnswerValue>>({});
  const [open, setOpen] = useState(!collapsible);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const visibleQuestions = useMemo(
    () => module.questions.filter((question) => questionIsVisible(question, answers)),
    [module.questions, answers],
  );

  const missingRequired = visibleQuestions.some(
    (question) => question.required && isEmptyAnswer(answers[question.id]),
  );

  function setAnswer(questionId: string, value: JourneyAnswerValue) {
    setAnswers((current) => ({ ...current, [questionId]: value }));
  }

  async function submit() {
    if (missingRequired) {
      setError("Preencha os campos obrigatórios antes de salvar.");
      return;
    }
    setBusy(true);
    setError(null);
    try {
      await save(module.id, occurredOn, answers);
      setAnswers({});
      if (collapsible) setOpen(false);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Não foi possível salvar o registro.");
    } finally {
      setBusy(false);
    }
  }

  return (
    <section className="rounded-xl bg-card p-4 shadow-[var(--shadow-border)]">
      <div className="flex items-start justify-between gap-3">
        <div className="min-w-0 flex-1">
          <h2 className="font-display text-lg font-semibold">{module.title}</h2>
          {module.instructions && (
            <p className="mt-1 text-sm leading-relaxed text-muted-foreground">
              {module.instructions}
            </p>
          )}
        </div>
        {collapsible && (
          <Button
            type="button"
            variant="ghost"
            size="icon"
            onClick={() => setOpen((value) => !value)}
            aria-label={open ? "Fechar registro" : "Abrir registro"}
          >
            {open ? <ChevronUp /> : <ChevronDown />}
          </Button>
        )}
      </div>

      {open && (
        <div className="mt-4 space-y-5">
          {visibleQuestions.map((question) => (
            <QuestionField
              key={question.id}
              question={question}
              value={answers[question.id]}
              onChange={(value) => setAnswer(question.id, value)}
            />
          ))}

          {module.questions.length === 0 && (
            <p className="text-sm text-muted-foreground">
              Confirme este item quando tiver realizado o que foi combinado na Jornada.
            </p>
          )}

          {error && <p className="text-sm text-destructive">{error}</p>}

          <Button type="button" className="w-full" disabled={busy} onClick={() => void submit()}>
            {busy ? "Salvando…" : module.questions.length ? "Salvar registro" : "Marcar como realizado"}
          </Button>
        </div>
      )}
    </section>
  );
}

function QuestionField({
  question,
  value,
  onChange,
}: {
  question: JourneyQuestion;
  value: JourneyAnswerValue | undefined;
  onChange: (value: JourneyAnswerValue) => void;
}) {
  const required = question.required ? " *" : "";

  if (question.type === "boolean" || question.type === "event") {
    return (
      <Field label={question.label + required}>
        <div className="grid grid-cols-2 gap-2">
          <ChoiceButton active={value === true} onClick={() => onChange(true)}>
            Sim
          </ChoiceButton>
          <ChoiceButton active={value === false} onClick={() => onChange(false)}>
            Não
          </ChoiceButton>
        </div>
      </Field>
    );
  }

  if (
    question.type === "single_choice" ||
    question.type === "emotion"
  ) {
    return (
      <Field label={question.label + required}>
        {(question.options ?? []).length ? (
          <div className="grid gap-2">
            {(question.options ?? []).map((option) => (
              <ChoiceButton
                key={option.id}
                active={value === option.id}
                onClick={() => onChange(option.id)}
              >
                {option.label}
              </ChoiceButton>
            ))}
          </div>
        ) : (
          <p className="text-xs text-muted-foreground">Sem opções configuradas.</p>
        )}
      </Field>
    );
  }

  if (question.type === "multiple_choice") {
    const selected = Array.isArray(value) ? value : [];
    return (
      <Field label={question.label + required}>
        <div className="grid gap-2">
          {(question.options ?? []).map((option) => {
            const active = selected.includes(option.id);
            return (
              <ChoiceButton
                key={option.id}
                active={active}
                onClick={() =>
                  onChange(
                    active
                      ? selected.filter((item) => item !== option.id)
                      : [...selected, option.id],
                  )
                }
              >
                <span className="flex items-center gap-2">
                  <span
                    className={cn(
                      "grid size-5 place-items-center rounded border text-[10px]",
                      active ? "border-primary-foreground" : "border-border",
                    )}
                  >
                    {active && <Check className="size-3" />}
                  </span>
                  {option.label}
                </span>
              </ChoiceButton>
            );
          })}
        </div>
      </Field>
    );
  }

  if (question.type === "scale" || question.type === "number") {
    return (
      <Field label={question.label + required}>
        <Input
          type="number"
          inputMode="decimal"
          min={question.min}
          max={question.max}
          step={question.step ?? 1}
          value={typeof value === "number" ? value : ""}
          onChange={(event) =>
            onChange(event.target.value === "" ? null : Number(event.target.value))
          }
        />
        {(question.min != null || question.max != null) && (
          <p className="mt-1 text-xs text-muted-foreground">
            {question.min != null ? `Mínimo: ${question.min}` : ""}
            {question.min != null && question.max != null ? " · " : ""}
            {question.max != null ? `Máximo: ${question.max}` : ""}
          </p>
        )}
      </Field>
    );
  }

  if (question.type === "duration") {
    return (
      <Field label={question.label + required}>
        <div className="flex items-center gap-2">
          <Input
            type="number"
            min={0}
            step={question.step ?? 5}
            inputMode="decimal"
            value={typeof value === "number" ? value : ""}
            onChange={(event) =>
              onChange(event.target.value === "" ? null : Number(event.target.value))
            }
          />
          <span className="text-sm text-muted-foreground">min</span>
        </div>
      </Field>
    );
  }

  if (question.type === "long_text") {
    return (
      <Field label={question.label + required}>
        <Textarea
          value={typeof value === "string" ? value : ""}
          onChange={(event) => onChange(event.target.value)}
        />
      </Field>
    );
  }

  return (
    <Field label={question.label + required}>
      <Input
        value={typeof value === "string" ? value : ""}
        onChange={(event) => onChange(event.target.value)}
      />
    </Field>
  );
}

function ChoiceButton({
  active,
  onClick,
  children,
}: {
  active: boolean;
  onClick: () => void;
  children: ReactNode;
}) {
  return (
    <button
      type="button"
      className={cn(
        "min-h-12 rounded-lg px-3 py-3 text-left text-sm transition-colors",
        active
          ? "bg-primary text-primary-foreground"
          : "bg-secondary text-secondary-foreground",
      )}
      onClick={onClick}
    >
      {children}
    </button>
  );
}

function Field({ label, children }: { label: string; children: ReactNode }) {
  return (
    <div className="space-y-2">
      <Label>{label}</Label>
      {children}
    </div>
  );
}

function questionIsVisible(
  question: JourneyQuestion,
  answers: Record<string, JourneyAnswerValue>,
): boolean {
  const condition = question.condition;
  if (!condition) return true;
  const current = answers[condition.questionId];

  if (condition.operator === "equals") return current === condition.value;
  if (condition.operator === "not_equals") {
    return current !== undefined && current !== condition.value;
  }
  if (condition.operator === "includes") {
    if (Array.isArray(current)) return current.includes(String(condition.value));
    if (typeof current === "string") return current.includes(String(condition.value));
    return false;
  }
  return true;
}

function isEmptyAnswer(value: JourneyAnswerValue | undefined): boolean {
  return (
    value === undefined ||
    value === null ||
    value === "" ||
    (Array.isArray(value) && value.length === 0)
  );
}

import { addMonths, format } from "date-fns";
import { ChevronLeft, ChevronRight } from "lucide-react";
import { useMemo, useState } from "react";
import { MonthGrid } from "@/components/month-grid";
import { Button } from "@/components/ui/button";
import {
  formatMonthTitle,
  formatSymptoms,
  hasAnyLog,
  monthStats,
  toKey,
} from "@/lib/calendar";
import { useJournal } from "@/lib/journal-store";
import type { DayLog } from "@/lib/types";

export function LegacyDoctorRecords() {
  const [month, setMonth] = useState(() => new Date());
  const days = useJournal((s) => s.days);
  const stats = useMemo(() => monthStats(month, days), [month, days]);
  const loggedDays = useMemo(
    () =>
      Object.entries(days)
        .filter(([key, log]) => key.startsWith(format(month, "yyyy-MM")) && hasAnyLog(log))
        .sort(([a], [b]) => b.localeCompare(a)),
    [days, month],
  );

  return (
    <div className="space-y-5">
      <header>
        <p className="text-xs font-medium uppercase tracking-[0.16em] text-primary">
          Registros do paciente
        </p>
        <h1 className="mt-1 font-display text-3xl font-semibold tracking-tight">
          Acompanhamento anterior
        </h1>
        <p className="mt-2 text-sm leading-relaxed text-muted-foreground">
          Visualização somente leitura dos registros feitos no modelo anterior da Jornada.
        </p>
      </header>

      <div className="flex items-center justify-between gap-3">
        <Button
          variant="outline"
          size="icon"
          onClick={() => setMonth((value) => addMonths(value, -1))}
          aria-label="Mês anterior"
        >
          <ChevronLeft />
        </Button>
        <h2 className="font-display text-xl font-semibold">
          {formatMonthTitle(month)}
        </h2>
        <Button
          variant="outline"
          size="icon"
          onClick={() => setMonth((value) => addMonths(value, 1))}
          aria-label="Próximo mês"
        >
          <ChevronRight />
        </Button>
      </div>

      <section className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
        <Metric label="Dias com registro" value={String(stats.daysLogged)} />
        <Metric label="Caminhadas" value={String(stats.walks)} />
        <Metric label="Treinos de força" value={String(stats.gymSessions)} />
        <Metric label="Noites com CPAP" value={String(stats.cpapNights)} />
      </section>

      <section className="rounded-xl bg-card p-4 shadow-[var(--shadow-border)]">
        <p className="mb-3 text-sm font-medium">Dias com algum registro</p>
        <MonthGrid
          month={month}
          renderCell={(cell) => <LegacyCell log={days[cell.key]} />}
        />
      </section>

      <section className="space-y-3">
        <h2 className="font-display text-lg font-semibold">Linha do tempo do mês</h2>
        {loggedDays.length === 0 ? (
          <div className="rounded-xl bg-card p-5 text-sm text-muted-foreground shadow-[var(--shadow-border)]">
            Nenhum registro neste mês.
          </div>
        ) : (
          loggedDays.map(([key, log]) => (
            <article
              key={key}
              className="rounded-xl bg-card p-4 shadow-[var(--shadow-border)]"
            >
              <p className="text-sm font-medium">
                {format(new Date(`${key}T12:00:00`), "dd/MM/yyyy")}
              </p>
              <dl className="mt-3 space-y-2 text-sm">
                {log.applied && <Row label="Medicação" value="Aplicação registrada" />}
                {log.symptoms?.length ? (
                  <Row label="Sintomas" value={formatSymptoms(log.symptoms)} />
                ) : null}
                {(log.aerobic?.walk ?? log.walkMinutes ?? 0) > 0 && (
                  <Row
                    label="Caminhada"
                    value={`${log.aerobic?.walk ?? log.walkMinutes ?? 0} min`}
                  />
                )}
                {Boolean(log.strength?.gym ?? log.gym) && (
                  <Row label="Musculação" value="Realizada" />
                )}
                {(log.cpapHours ?? 0) > 0 && (
                  <Row label="CPAP" value={`${log.cpapHours} h`} />
                )}
                {(log.sleepHours ?? 0) > 0 && (
                  <Row label="Sono" value={`${log.sleepHours} h`} />
                )}
                {log.meals && <Row label="Alimentação" value={mealLabel(log.meals)} />}
                {log.social && <Row label="Conexões sociais" value={socialLabel(log.social)} />}
              </dl>
            </article>
          ))
        )}
      </section>
    </div>
  );
}

function LegacyCell({ log }: { log?: DayLog }) {
  if (!hasAnyLog(log)) return null;
  return <span className="inline-block size-2 rounded-full bg-primary" aria-label="Com registro" />;
}

function Metric({ label, value }: { label: string; value: string }) {
  return (
    <div className="rounded-xl bg-card p-4 shadow-[var(--shadow-border)]">
      <p className="text-xs text-muted-foreground">{label}</p>
      <p className="mt-1 font-display text-xl font-semibold tabular-nums">{value}</p>
    </div>
  );
}

function Row({ label, value }: { label: string; value: string }) {
  return (
    <div className="flex items-baseline justify-between gap-4">
      <dt className="text-muted-foreground">{label}</dt>
      <dd className="text-right font-medium">{value}</dd>
    </div>
  );
}

function mealLabel(value: NonNullable<DayLog["meals"]>): string {
  if (value === "ok") return "Rotina registrada";
  if (value === "fast") return "Jejum prolongado";
  return "Improvisação das refeições";
}

function socialLabel(value: NonNullable<DayLog["social"]>): string {
  if (value === "support") return "Rede de apoio";
  if (value === "present") return "Presença/conexão";
  return "Solidão percebida";
}

