import type { ReactNode } from "react";
import { WEEKDAYS_MON } from "@/lib/constants";
import { isInjectionDay, monthGrid, type GridCell } from "@/lib/calendar";
import { cn } from "@/lib/utils";

type Props = {
  month: Date;
  injectionWeekday?: number | null;
  renderCell: (cell: GridCell) => ReactNode;
  onSelect?: (cell: GridCell) => void;
};

export function MonthGrid({ month, injectionWeekday = null, renderCell, onSelect }: Props) {
  const cells = monthGrid(month);

  return (
    <div>
      <div className="mb-1 grid grid-cols-7 text-center text-[10px] font-semibold tracking-wide text-muted-foreground">
        {WEEKDAYS_MON.map((d) => (
          <div key={d} className="py-1 whitespace-nowrap">
            {d}
          </div>
        ))}
      </div>
      <div className="grid grid-cols-7 gap-1">
        {cells.map((cell) => {
          const inj = cell.inMonth && isInjectionDay(cell.date, injectionWeekday);
          return (
            <button
              key={cell.key}
              type="button"
              disabled={!cell.inMonth}
              onClick={() => cell.inMonth && onSelect?.(cell)}
              className={cn(
                "relative flex min-h-14 flex-col items-stretch overflow-hidden rounded-md p-1 text-left transition-colors",
                cell.inMonth
                  ? "bg-card shadow-[var(--shadow-border)] hover:bg-accent/60"
                  : "opacity-0",
                cell.isToday && cell.inMonth && "ring-2 ring-primary/50",
                inj && "bg-accent",
              )}
            >
              <span
                className={cn(
                  "whitespace-nowrap text-[11px] font-semibold tabular-nums leading-none",
                  cell.isToday ? "text-primary" : "text-muted-foreground",
                )}
              >
                {cell.date.getDate()}
              </span>
              <div className="mt-1 min-h-5 flex-1 overflow-hidden text-[10px] leading-tight">
                {cell.inMonth ? renderCell(cell) : null}
              </div>
            </button>
          );
        })}
      </div>
    </div>
  );
}

import { useEffect } from "react";
import { Bell } from "lucide-react";
import { Button } from "@/components/ui/button";
import { useJournal } from "@/lib/journal-store";

export function NoticeFeed() {
  const notices = useJournal((s) => s.notices);
  const refreshNotices = useJournal((s) => s.refreshNotices);
  const markNoticesRead = useJournal((s) => s.markNoticesRead);
  const openPatient = useJournal((s) => s.openPatient);
  const unread = notices.filter((n) => !n.read).length;

  useEffect(() => {
    void refreshNotices();
    const id = window.setInterval(() => void refreshNotices(), 45_000);
    return () => window.clearInterval(id);
  }, [refreshNotices]);

  if (!notices.length) {
    return (
      <section className="rounded-xl bg-card p-5 shadow-[var(--shadow-border)]">
        <h2 className="flex items-center gap-2 font-display text-lg font-semibold">
          <Bell className="size-4 text-primary" />
          Atividade recente
        </h2>
        <p className="mt-2 text-sm text-muted-foreground">
          Aqui aparecem registros e ações recentes do paciente. Alertas configurados ficam em uma área separada.
        </p>
      </section>
    );
  }

  return (
    <section className="rounded-xl bg-card p-5 shadow-[var(--shadow-border)]">
      <div className="mb-3 flex items-center justify-between gap-2">
        <h2 className="flex items-center gap-2 font-display text-lg font-semibold">
          <Bell className="size-4 text-primary" />
          Atividade recente
          {unread > 0 && (
            <span className="rounded-full bg-primary px-2 py-0.5 text-xs text-primary-foreground">
              {unread}
            </span>
          )}
        </h2>
        {unread > 0 && (
          <Button type="button" variant="ghost" size="sm" onClick={() => void markNoticesRead()}>
            Marcar lidos
          </Button>
        )}
      </div>
      <ul className="space-y-3">
        {notices.slice(0, 12).map((n) => (
          <li key={n.id}>
            <button
              type="button"
              onClick={() => {
                if (!n.read) void markNoticesRead([n.id]);
                void openPatient(n.journeyId);
              }}
              className="w-full rounded-lg px-3 py-3 text-left hover:bg-secondary"
            >
              <p className="text-sm font-medium">
                {!n.read && (
                  <span className="mr-2 inline-block size-2 rounded-full bg-primary align-middle" />
                )}
                {n.patientName}
              </p>
              <p className="mt-0.5 text-sm leading-relaxed text-muted-foreground">{n.summary}</p>
            </button>
          </li>
        ))}
      </ul>
    </section>
  );
}

import { useState } from "react";
